424	type IsAny<T> = 0 extends 1 & T ? true : false;
425	type IsExactlyJsonValue<T> = [T] extends [JsonValue] ? ([JsonValue] extends [T] ? true : false) : false;
426	type IsJsonProperty<T> = IsAny<T> extends true
427		? false
428		: unknown extends T
429			? false
430			: [Exclude<T, undefined>] extends [never]
431				? true
432				: IsJsonCompatible<Exclude<T, undefined>>;
433	type InvalidJsonKeys<T extends object> = {
434		[TKey in keyof T]-?: TKey extends string | number ? (IsJsonProperty<T[TKey]> extends true ? never : TKey) : TKey;
435	}[keyof T];
436	type IsJsonCompatible<T> = IsAny<T> extends true
437		? false
438		: unknown extends T
439			? false
440			: IsExactlyJsonValue<T> extends true
441				? true
442				: T extends null | boolean | number | string
443					? true
444					: T extends undefined
445						? false
446						: T extends readonly (infer TItem)[]
447							? IsJsonCompatible<TItem>
448							: T extends (...args: never[]) => unknown
449								? false
450								: T extends object
451									? [InvalidJsonKeys<T>] extends [never]
452										? true
453										: false
454									: false;
455	
456	/** The JSON representation of a typed in-memory value. Optional object properties remain optional. */
457	export type JsonRepresentation<T> = IsAny<T> extends true
458		? JsonValue
459		: unknown extends T
460			? JsonValue
461			: [T] extends [JsonValue]
462				? T
463				: T extends readonly unknown[]
464					? { [TKey in keyof T]: JsonRepresentation<Exclude<T[TKey], undefined>> }
465					: T extends object
466						? { [TKey in keyof T]: JsonRepresentation<Exclude<T[TKey], undefined>> }
467						: never;
