636	/**
637	 * Event protocol for AssistantMessageEventStream.
638	 *
639	 * Successful streams emit `start` before partial updates and terminate with
640	 * `done`. A stream may terminate directly with `error` when request setup fails
641	 * before generation starts; after `start`, failures also terminate with `error`.
642	 * Direct `streamSimple()` calls throw synchronously when request auth is missing.
643	 * Updates and `done` must never appear before `start`.
644	 *
645	 * `partial` is the shared live response-so-far helper, not an event-time
646	 * snapshot. Text and thinking blocks are empty when their `*_start` event is
647	 * emitted and grow only through their corresponding `*_delta` events until the
648	 * authoritative `*_end`. Redacted thinking may be complete at start and emit no
649	 * deltas. Tool-call arguments at `toolcall_start` are provider-specific;
650	 * `toolcall_delta` carries subsequent JSON updates.
651	 */
652	export type AssistantMessageEvent =
653		| { type: "start"; partial: AssistantMessage }
654		| { type: "text_start"; contentIndex: number; partial: AssistantMessage }
655		| { type: "text_delta"; contentIndex: number; delta: string; partial: AssistantMessage }
656		| { type: "text_end"; contentIndex: number; content: string; partial: AssistantMessage }
657		| { type: "thinking_start"; contentIndex: number; partial: AssistantMessage }
658		| { type: "thinking_delta"; contentIndex: number; delta: string; partial: AssistantMessage }
659		| { type: "thinking_end"; contentIndex: number; content: string; partial: AssistantMessage }
660		| { type: "toolcall_start"; contentIndex: number; partial: AssistantMessage }
661		| { type: "toolcall_delta"; contentIndex: number; delta: string; partial: AssistantMessage }
662		| { type: "toolcall_end"; contentIndex: number; toolCall: ToolCall; partial: AssistantMessage }
663		| {
664				type: "done";
665				reason: Extract<StopReason, "stop" | "length" | "toolUse" | "deferred">;
666				message: AssistantMessage;
667		  }
668		| { type: "error"; reason: Extract<StopReason, "aborted" | "error">; error: AssistantMessage };
