719		 * Top-level request field used to cap reasoning tokens from `thinkingBudgets`.
720		 * Reasoning and the answer share `max_tokens` on these endpoints, so without a budget a
721		 * reasoning-heavy turn can consume the whole response and emit no answer.
722		 * `"thinking_token_budget"` is vLLM, `"thinking_budget"` is Qwen/DashScope/SGLang,
723		 * `"thinking_budget_tokens"` is llama.cpp. Off by default; not set on the generated catalog.
724		 */
725		thinkingTokenBudgetField?: ThinkingTokenBudgetField;
726		/** Alias for `thinkingTokenBudgetField: "thinking_token_budget"` (vLLM). Prefer `thinkingTokenBudgetField`. Default: false. */
727		supportsThinkingTokenBudget?: boolean;
728		/** Whether the provider supports OpenAI custom tools with Lark/regex grammar formats. When false, grammar-constrained tools fall back to normal function tools. Default: false; the generated model catalog enables it for capable models. */
729		supportsOpenAIGrammarTools?: boolean;
730		/** Whether the exact model accepts system or developer messages after the conversation has started. When false, later system messages are folded into the leading system message. Default: false; the generated model catalog enables it for verified models. */
731		supportsMidConvoSystemMessages?: boolean;
732		/** Whether system messages can introduce additional tools mid-conversation. Requires `supportsMidConvoSystemMessages`. Default: false; the generated model catalog enables it for capable models. */
733		supportsMidConvoToolAdditions?: boolean;
734		/** Whether the provider supports the `strict` field in tool definitions. Default: false; generated capable models enable it explicitly. */
735		supportsStrictMode?: boolean;
736		/** Cache control convention for prompt caching. "anthropic" applies Anthropic-style `cache_control` markers to the system prompt, last tool definition, and last user, assistant, or tool-result text content. */
737		cacheControlFormat?: "anthropic";
738		/** Whether to send session-affinity data from `options.sessionId`. Default: true for OpenRouter endpoints, false otherwise. */
739		sendSessionAffinityHeaders?: boolean;
740		/** Session-affinity header format: `openai` sends `session_id`, `x-client-request-id`, and `x-session-affinity`; `openai-nosession` sends `x-client-request-id` and `x-session-affinity`; `openrouter` sends `x-session-id`. Does not affect the `prompt_cache_key` body param, which is governed by cache retention. Default: auto-detected. */
741		sessionAffinityFormat?: SessionAffinityFormat;
742		/** Whether the provider supports long prompt cache retention (`prompt_cache_retention: "24h"` or Anthropic-style `cache_control.ttl: "1h"`, depending on format). Default: true. */
743		supportsLongCacheRetention?: boolean;
744		/**
745		 * vLLM scheduler priority sent as the top-level `priority` request field (lower values are
746		 * handled earlier; server default 0). Only meaningful when vLLM runs with
747		 * `--scheduling-policy priority`; useful for keeping background/batch work from stalling
748		 * interactive sessions. Off by default; not set on the generated catalog.
749		 */
750		vllmPriority?: number;
751	}
752	
753	/** Compatibility settings for OpenAI Responses APIs. */
754	export interface OpenAIResponsesCompat {
755		/** Whether the provider supports the `developer` role (vs `system`). Default: true. */
756		supportsDeveloperRole?: boolean;
757		/** Whether the exact model accepts developer or system messages after the conversation has started. When false, later system messages are folded into the leading system message. Default: false; the generated model catalog enables it for verified models. */
758		supportsMidConvoSystemMessages?: boolean;
759		/** Session-affinity header format: `openai` sends `session_id` and `x-client-request-id`; `openai-nosession` sends `x-client-request-id`; `openrouter` sends `x-session-id`. Does not affect the `prompt_cache_key` body param, which is governed by cache retention. Default: auto-detected. */
760		sessionAffinityFormat?: SessionAffinityFormat;
761		/** Whether the provider supports long prompt cache retention. This uses `prompt_cache_options.ttl: "30m"` on GPT-5.6+ and `prompt_cache_retention: "24h"` on earlier models. Default: true. */
762		supportsLongCacheRetention?: boolean;
763		/** Whether the provider supports strict JSON-schema function tools. Defaults are API-specific; generated OpenAI models enable it explicitly. */
764		supportsStrictMode?: boolean;
765		/** Whether to emit OpenAI custom tools with Lark/regex grammar formats. When false, grammar-constrained tools fall back to normal function tools. Default: false; the generated model catalog enables it for capable models. */
766		supportsOpenAIGrammarTools?: boolean;
767		/** Whether the model supports message-anchored `additional_tools` input items. Default: false. */
768		supportsAdditionalTools?: boolean;
