770		supportsToolSearch?: boolean;
771		/** Whether the model accepts `prompt_cache_options` (OpenAI GPT-5.6+ prompt caching). Older OpenAI models reject the parameter. Default: false. */
772		supportsExplicitPromptCacheMode?: boolean;
