807		/**
808		 * Whether the model accepts the Anthropic `temperature` request field.
809		 * Claude Opus 4.7+ rejects non-default temperature values.
810		 * Default: true.
811		 */
812		supportsTemperature?: boolean;
813		/**
814		 * Whether to force adaptive thinking (`thinking.type: "adaptive"` plus
815		 * `output_config.effort`) regardless of the model id. Built-in models that
816		 * require adaptive thinking set this in generated metadata. Custom
817		 * Anthropic-compatible providers can set this to `true` for any model whose
818		 * upstream requires the adaptive format. Set to `false` to
819		 * opt out on overridden built-in models.
820		 * Default: false.
