823		/** Whether to replay empty thinking signatures as `signature: ""` instead of converting thinking to text. Default: false. */
824		allowEmptySignature?: boolean;
825		/** Whether the provider supports Anthropic strict tool schemas. Default: false; generated Anthropic models enable it explicitly. */
826		supportsStrictTools?: boolean;
