828		supportsMidConvoEffort?: boolean;
829		/** Whether the exact model accepts system-role messages inside the conversation. When false, later system messages are folded into the top-level system prompt. Default: false. */
830		supportsMidConvoSystemMessages?: boolean;
831		/** Whether the exact model accepts mid-conversation `tool_addition` and `tool_removal` blocks. Requires `supportsMidConvoSystemMessages`. Default: false. */
832		supportsMidConvoToolChanges?: boolean;
833		/**
834		 * Models Anthropic accepts in `fallbacks` for server-side refusal fallback,
835		 * with local pricing metadata for returned fallback responses. When absent or
836		 * empty, callers must omit `fallbacks`; Anthropic rejects the field for models
837		 * with no permitted fallback targets.
838		 */
839		allowedFallbackModels?: AnthropicAllowedFallbackModel[];
840	}
841	
