851		supportsMidConvoSystemMessages?: boolean;
852	}
853	
854	/**
855	 * OpenRouter provider routing preferences.
856	 * Controls which upstream providers OpenRouter routes requests to.
857	 * Sent as the `provider` field in the OpenRouter API request body.
858	 * @see https://openrouter.ai/docs/guides/routing/provider-selection
859	 */
860	export interface OpenRouterRouting {
861		/** Whether to allow backup providers to serve requests. Default: true. */
862		allow_fallbacks?: boolean;
863		/** Whether to filter providers to only those that support all parameters in the request. Default: false. */
864		require_parameters?: boolean;
865		/** Data collection setting. "allow" (default): allow providers that may store/train on data. "deny": only use providers that don't collect user data. */
866		data_collection?: "deny" | "allow";
867		/** Whether to restrict routing to only ZDR (Zero Data Retention) endpoints. */
868		zdr?: boolean;
869		/** Whether to restrict routing to only models that allow text distillation. */
870		enforce_distillable_text?: boolean;
871		/** An ordered list of provider names/slugs to try in sequence, falling back to the next if unavailable. */
872		order?: string[];
873		/** List of provider names/slugs to exclusively allow for this request. */
874		only?: string[];
875		/** List of provider names/slugs to skip for this request. */
876		ignore?: string[];
877		/** A list of quantization levels to filter providers by (e.g., ["fp16", "bf16", "fp8", "fp6", "int8", "int4", "fp4", "fp32"]). */
878		quantizations?: string[];
879		/** Sorting strategy. Can be a string (e.g., "price", "throughput", "latency") or an object with `by` and `partition`. */
880		sort?:
881			| string
882			| {
883					/** The sorting metric: "price", "throughput", "latency". */
884					by?: string;
885					/** Partitioning strategy: "model" (default) or "none". */
886					partition?: string | null;
887			  };
888		/** Maximum price per million tokens (USD). */
889		max_price?: {
890			/** Price per million prompt tokens. */
891			prompt?: number | string;
892			/** Price per million completion tokens. */
893			completion?: number | string;
894			/** Price per image. */
895			image?: number | string;
896			/** Price per audio unit. */
897			audio?: number | string;
898			/** Price per request. */
899			request?: number | string;
900		};
901		/** Preferred minimum throughput (tokens/second). Can be a number (applies to p50) or an object with percentile-specific cutoffs. */
902		preferred_min_throughput?:
903			| number
904			| {
905					/** Minimum tokens/second at the 50th percentile. */
906					p50?: number;
907					/** Minimum tokens/second at the 75th percentile. */
908					p75?: number;
909					/** Minimum tokens/second at the 90th percentile. */
910					p90?: number;
911					/** Minimum tokens/second at the 99th percentile. */
912					p99?: number;
913			  };
914		/** Preferred maximum latency (seconds). Can be a number (applies to p50) or an object with percentile-specific cutoffs. */
915		preferred_max_latency?:
916			| number
917			| {
918					/** Maximum latency in seconds at the 50th percentile. */
919					p50?: number;
920					/** Maximum latency in seconds at the 75th percentile. */
921					p75?: number;
922					/** Maximum latency in seconds at the 90th percentile. */
923					p90?: number;
924					/** Maximum latency in seconds at the 99th percentile. */
925					p99?: number;
926			  };
927	}
928	
929	/**
930	 * Vercel AI Gateway routing preferences.
931	 * Controls which upstream providers the gateway routes requests to.
932	 * @see https://vercel.com/docs/ai-gateway/models-and-providers/provider-options
933	 */
934	export interface VercelGatewayRouting {
935		/** List of provider slugs to exclusively use for this request (e.g., ["bedrock", "anthropic"]). */
936		only?: string[];
937		/** List of provider slugs to try in order (e.g., ["anthropic", "openai"]). */
938		order?: string[];
939	}
940	
941	export interface ModelCostRates {
942		input: number; // $/million tokens
943		output: number; // $/million tokens
944		cacheRead: number; // $/million tokens
945		cacheWrite: number; // $/million tokens
946	}
947	
