991		 * Missing keys use provider defaults. null marks a level as unsupported.
992		 */
993		thinkingLevelMap?: ThinkingLevelMap;
994		input: ("text" | "image")[];
995		/** Provider input limits and cache-safe preprocessing metadata. */
