1	/**
2	 * Agent loop that works with AgentMessage throughout.
3	 * Transforms to Message[] only at the LLM call boundary.
4	 */
5	
6	import {
7		type AssistantMessage,
8		EventStream,
9		getCurrentTools,
10		getToolStateChanges,
11		normalizeContext,
12		type SystemMessage,
13		type ToolResultMessage,
14		type ToolStateChanges,
15		toToolDeclaration,
16		validateToolArguments,
17	} from "@earendil-works/pi-ai";
18	import { getDefaultStreamFn } from "./stream-fn.ts";
19	import type {
20		AgentContext,
21		AgentEvent,
22		AgentLoopConfig,
23		AgentMessage,
24		AgentTool,
25		AgentToolCall,
26		AgentToolResult,
27		PrepareNextTurnContext,
