31	export type AgentEventSink = (event: AgentEvent) => Promise<void> | void;
32	
33	/**
34	 * Start an agent loop with a new prompt message.
35	 * The prompt is added to the context and events are emitted for it.
36	 */
37	export function agentLoop(
38		prompts: AgentMessage[],
39		context: AgentContext,
40		config: AgentLoopConfig,
41		signal: AbortSignal | undefined,
42		streamFn: StreamFn,
43	): EventStream<AgentEvent, AgentMessage[]> {
44		const stream = createAgentStream();
45	
46		void runAgentLoop(
47			prompts,
48			context,
49			config,
50			async (event) => {
51				stream.push(event);
52			},
53			signal,
54			streamFn,
55		).then((messages) => {
56			stream.end(messages);
57		});
58	
59		return stream;
60	}
61	
62	/**
63	 * Continue an agent loop from the current context without adding a new message.
64	 * Used for retries - context already has user message or tool results.
65	 *
66	 * **Important:** The last message in context must convert to a `user` or `toolResult` message
67	 * via `convertToLlm`. If it doesn't, the LLM provider will reject the request.
68	 * This cannot be validated here since `convertToLlm` is only called once per turn.
69	 */
70	export function agentLoopContinue(
71		context: AgentContext,
72		config: AgentLoopConfig,
73		signal: AbortSignal | undefined,
74		streamFn: StreamFn,
75	): EventStream<AgentEvent, AgentMessage[]> {
76		if (context.messages.length === 0) {
77			throw new Error("Cannot continue: no messages in context");
78		}
79	
80		if (context.messages[context.messages.length - 1].role === "assistant") {
81			throw new Error("Cannot continue from message role: assistant");
82		}
83	
84		const stream = createAgentStream();
85	
86		void runAgentLoopContinue(
87			context,
88			config,
89			async (event) => {
90				stream.push(event);
91			},
92			signal,
93			streamFn,
94		).then((messages) => {
95			stream.end(messages);
96		});
97	
98		return stream;
99	}
