101	export async function runAgentLoop(
102		prompts: AgentMessage[],
103		context: AgentContext,
104		config: AgentLoopConfig,
105		emit: AgentEventSink,
106		signal: AbortSignal | undefined,
107		streamFn: StreamFn,
108	): Promise<AgentMessage[]> {
109		const initialMessages = declareToolChanges(context, prompts);
110		const newMessages: AgentMessage[] = [...initialMessages];
111		const currentContext: AgentContext = {
112			...context,
113			messages: [...context.messages, ...initialMessages],
114		};
115	
116		await emit({ type: "agent_start" });
117		await emit({ type: "turn_start" });
118		for (const message of initialMessages) {
119			await emit({ type: "message_start", message });
120			await emit({ type: "message_end", message });
121		}
122	
123		await runLoop(currentContext, newMessages, config, signal, emit, streamFn ?? getDefaultStreamFn());
124		return newMessages;
125	}
126	
127	export async function runAgentLoopContinue(
128		context: AgentContext,
129		config: AgentLoopConfig,
130		emit: AgentEventSink,
131		signal: AbortSignal | undefined,
132		streamFn: StreamFn,
133	): Promise<AgentMessage[]> {
134		if (context.messages.length === 0) {
135			throw new Error("Cannot continue: no messages in context");
136		}
137	
138		if (context.messages[context.messages.length - 1].role === "assistant") {
139			throw new Error("Cannot continue from message role: assistant");
140		}
141	
142		const newMessages: AgentMessage[] = [];
143		const currentContext: AgentContext = { ...context };
144	
145		await emit({ type: "agent_start" });
146		await emit({ type: "turn_start" });
147	
148		await runLoop(currentContext, newMessages, config, signal, emit, streamFn ?? getDefaultStreamFn());
149		return newMessages;
150	}
151	
152	function createAgentStream(): EventStream<AgentEvent, AgentMessage[]> {
153		return new EventStream<AgentEvent, AgentMessage[]>(
154			(event: AgentEvent) => event.type === "agent_end",
155			(event: AgentEvent) => (event.type === "agent_end" ? event.messages : []),
156		);
157	}
158	
159	/**
160	 * Main loop logic shared by agentLoop and agentLoopContinue.
161	 */
162	async function runLoop(
163		initialContext: AgentContext,
164		newMessages: AgentMessage[],
165		initialConfig: AgentLoopConfig,
166		signal: AbortSignal | undefined,
167		emit: AgentEventSink,
168		streamFunction: StreamFn,
169	): Promise<void> {
170		let currentContext = initialContext;
171		let config = initialConfig;
172		let lastCompletedTurn: PrepareNextTurnContext | undefined;
173		let explicitContinuation = false;
174		// Check for steering messages at start (user may have typed while waiting)
175		let pendingMessages: AgentMessage[] = (await config.getSteeringMessages?.()) || [];
176	
177		// Outer loop: continues when queued follow-up messages arrive after agent would stop
178		while (true) {
179			let hasMoreToolCalls = true;
180	
181			// Inner loop: process tool calls and steering messages
182			while (hasMoreToolCalls || pendingMessages.length > 0) {
183				let preparedMessages: AgentMessage[] = [];
184				if (lastCompletedTurn) {
185					const nextTurnSnapshot = await config.prepareNextTurn?.(lastCompletedTurn);
186					if (nextTurnSnapshot) {
187						currentContext = nextTurnSnapshot.context ?? currentContext;
188						preparedMessages = nextTurnSnapshot.messages ?? [];
189						config = {
190							...config,
191							model: nextTurnSnapshot.model ?? config.model,
192							reasoning:
193								nextTurnSnapshot.thinkingLevel === undefined
194									? config.reasoning
195									: nextTurnSnapshot.thinkingLevel === "off"
196										? undefined
197										: nextTurnSnapshot.thinkingLevel,
198						};
199					}
200					// Preparation can be long-running (for example, compaction). Pick up steering
201					// queued while it ran. Only poll again if the earlier poll returned nothing;
202					// otherwise one-at-a-time mode would deliver two messages in this turn.
203					if (pendingMessages.length === 0) {
204						pendingMessages = (await config.getSteeringMessages?.()) || [];
205					}
206					await emit({ type: "turn_start" });
207				}
208	
209				// Process prepared and queued messages before the next assistant response.
210				for (const message of declareToolChanges(currentContext, [...preparedMessages, ...pendingMessages])) {
211					await emit({ type: "message_start", message });
212					await emit({ type: "message_end", message });
213					currentContext.messages.push(message);
214					newMessages.push(message);
215				}
216				pendingMessages = [];
217	
218				const requestUpdate = await config.prepareRequest?.(
219					{
220						context: currentContext,
221						model: config.model,
222						thinkingLevel: config.reasoning ?? "off",
223					},
224					signal,
225				);
226				if (requestUpdate) {
227					currentContext = requestUpdate.context ?? currentContext;
228					config = {
229						...config,
230						model: requestUpdate.model ?? config.model,
231						reasoning:
232							requestUpdate.thinkingLevel === undefined
233								? config.reasoning
234								: requestUpdate.thinkingLevel === "off"
235									? undefined
236									: requestUpdate.thinkingLevel,
237					};
238				}
239	
240				// Stream assistant response
241				const message = await streamAssistantResponse(currentContext, config, signal, emit, streamFunction);
242				newMessages.push(message);
243	
244				if (message.stopReason === "error" || message.stopReason === "aborted") {
245					lastCompletedTurn = {
246						message,
247						toolResults: [],
248						context: currentContext,
249						newMessages,
250					};
251					await config.finishTurn?.(lastCompletedTurn, signal);
252					await emit({ type: "turn_end", message, toolResults: [] });
253					await emit({ type: "agent_end", messages: newMessages });
254					return;
255				}
256	
257				// Check for tool calls
258				const toolCalls = message.content.filter((c) => c.type === "toolCall");
259	
260				const toolResults: ToolResultMessage[] = [];
261				hasMoreToolCalls = false;
262				if (toolCalls.length > 0) {
263					// A "length" stop means the output was cut off by the token limit, so
264					// every tool call in the message may carry truncated arguments. Fail
265					// them all instead of executing potentially borked calls.
266					const executedToolBatch =
267						message.stopReason === "length"
268							? await failToolCallsFromTruncatedMessage(toolCalls, emit)
269							: await executeToolCalls(currentContext, message, config, signal, emit);
270					toolResults.push(...executedToolBatch.messages);
271					hasMoreToolCalls = !executedToolBatch.terminate;
272	
273					for (const result of toolResults) {
274						currentContext.messages.push(result);
275						newMessages.push(result);
276					}
277				}
278	
279				lastCompletedTurn = {
280					message,
281					toolResults,
282					context: currentContext,
283					newMessages,
284				};
285				const decision = await config.finishTurn?.(lastCompletedTurn, signal);
286				await emit({ type: "turn_end", message, toolResults });
287	
288				if (decision?.action === "end") {
289					await emit({ type: "agent_end", messages: newMessages });
290					return;
291				}
292	
293				explicitContinuation = decision?.action === "continue";
294				pendingMessages = (await config.getSteeringMessages?.()) || [];
295				if (hasMoreToolCalls || pendingMessages.length > 0) {
296					explicitContinuation = false;
297				}
298			}
299	
300			// Agent would stop here. Check for follow-up messages.
301			const followUpMessages = (await config.getFollowUpMessages?.()) || [];
302			if (followUpMessages.length > 0) {
303				// Set as pending so inner loop processes them
304				explicitContinuation = false;
305				pendingMessages = followUpMessages;
306				continue;
307			}
308	
309			// No natural request was selected, so fulfill the continuation decision with one context-only turn.
310			if (explicitContinuation) {
311				explicitContinuation = false;
312				continue;
313			}
314	
315			// No more messages, exit
316			break;
317		}
318	
319		await emit({ type: "agent_end", messages: newMessages });
320	}
321	
322	/**
323	 * Declare tool loadout changes to the model.
324	 *
325	 * `context.tools` is what the runtime can execute; the transcript's system messages declare
326	 * what the model may call. Before each request the difference becomes `toolsAdded` and
327	 * `toolsRemoved` on a system message. When a pending system message exists, its tool fields
328	 * are treated as intent and replaced with the delta between the committed transcript and
329	 * the executable set, so replay always yields exactly `context.tools`. Otherwise a new
330	 * system message is inserted before the first non-system pending message.
331	 */
332	function declareToolChanges(context: AgentContext, pendingMessages: AgentMessage[]): AgentMessage[] {
333		let systemIndex = -1;
334		for (let i = pendingMessages.length - 1; i >= 0; i--) {
335			if (pendingMessages[i].role === "system") {
336				systemIndex = i;
337				break;
338			}
339		}
340		const pending = pendingMessages[systemIndex] as SystemMessage | undefined;
341		const baseline = pending
342			? pendingMessages.map((message, index) =>
343					index === systemIndex ? withToolChanges(pending, NO_CHANGES) : message,
344				)
345			: pendingMessages;
346		const changes = getToolStateChanges(
347			getCurrentTools([...context.messages, ...baseline]),
348			(context.tools ?? []).map(toToolDeclaration),
349		);
350		const unchanged = changes.toolsAdded.length === 0 && changes.toolsRemoved.length === 0;
351	
352		if (pending) {
353			// Keep the caller's message object when it already declares no tool changes.
354			if (unchanged && !pending.toolsAdded?.length && !pending.toolsRemoved?.length) return pendingMessages;
355			return baseline.map((message, index) => (index === systemIndex ? withToolChanges(pending, changes) : message));
356		}
357		if (unchanged) return pendingMessages;
358		const update = withToolChanges({ role: "system", content: "", timestamp: Date.now() }, changes);
359		const insertIndex = pendingMessages.findIndex((message) => message.role !== "system");
360		const index = insertIndex === -1 ? pendingMessages.length : insertIndex;
361		return [...pendingMessages.slice(0, index), update, ...pendingMessages.slice(index)];
362	}
363	
364	const NO_CHANGES: ToolStateChanges = { toolsAdded: [], toolsRemoved: [] };
365	
366	/** Copy a system message with its tool fields replaced by `changes`; empty lists omit the field. */
367	function withToolChanges(message: SystemMessage, { toolsAdded, toolsRemoved }: ToolStateChanges): SystemMessage {
368		const { toolsAdded: _added, toolsRemoved: _removed, ...rest } = message;
369		return {
370			...rest,
371			...(toolsAdded.length > 0 ? { toolsAdded } : {}),
372			...(toolsRemoved.length > 0 ? { toolsRemoved } : {}),
373		};
374	}
375	
376	/**
377	 * Stream an assistant response from the LLM.
378	 * This is where AgentMessage[] gets transformed to Message[] for the LLM.
379	 */
380	async function streamAssistantResponse(
381		context: AgentContext,
382		config: AgentLoopConfig,
383		signal: AbortSignal | undefined,
384		emit: AgentEventSink,
385		streamFunction: StreamFn,
386	): Promise<AssistantMessage> {
387		// Apply context transform if configured (AgentMessage[] → AgentMessage[])
388		let messages = context.messages;
389		if (config.transformContext) {
390			messages = await config.transformContext(messages, signal);
391		}
392	
393		// Convert to LLM-compatible messages (AgentMessage[] → Message[])
394		const llmMessages = await config.convertToLlm(messages);
395	
396		const llmContext = normalizeContext({ messages: llmMessages });
397	
398		// Resolve API key (important for expiring tokens)
399		const resolvedApiKey =
400			(config.getApiKey ? await config.getApiKey(config.model.provider) : undefined) || config.apiKey;
401	
402		const response = await streamFunction(config.model, llmContext, {
403			...config,
404			apiKey: resolvedApiKey,
405			signal,
406		});
407	
408		let partialMessage: AssistantMessage | null = null;
409		let addedPartial = false;
410	
411		for await (const event of response) {
412			switch (event.type) {
413				case "start":
414					partialMessage = event.partial;
415					context.messages.push(partialMessage);
416					addedPartial = true;
417					await emit({ type: "message_start", message: { ...partialMessage } });
418					break;
419	
420				case "text_start":
421				case "text_delta":
422				case "text_end":
423				case "thinking_start":
424				case "thinking_delta":
425				case "thinking_end":
426				case "toolcall_start":
427				case "toolcall_delta":
428				case "toolcall_end":
429					if (partialMessage) {
430						partialMessage = event.partial;
431						context.messages[context.messages.length - 1] = partialMessage;
432						await emit({
433							type: "message_update",
434							assistantMessageEvent: event,
435							message: { ...partialMessage },
436						});
437					}
438					break;
439	
440				case "done":
441				case "error": {
442					const finalMessage = await response.result();
443					if (addedPartial) {
444						context.messages[context.messages.length - 1] = finalMessage;
445					} else {
446						context.messages.push(finalMessage);
447					}
448					if (!addedPartial) {
449						await emit({ type: "message_start", message: { ...finalMessage } });
450					}
451					await emit({ type: "message_end", message: finalMessage });
452					return finalMessage;
453				}
454			}
455		}
456	
457		const finalMessage = await response.result();
458		if (addedPartial) {
459			context.messages[context.messages.length - 1] = finalMessage;
460		} else {
461			context.messages.push(finalMessage);
462			await emit({ type: "message_start", message: { ...finalMessage } });
463		}
464		await emit({ type: "message_end", message: finalMessage });
465		return finalMessage;
466	}
467	
468	/**
469	 * Fail all tool calls from an assistant message that was truncated by the
470	 * output token limit. Streamed tool-call arguments are finalized with a
471	 * best-effort JSON salvage parser, so a truncated message can yield tool calls
472	 * whose arguments parse and validate but are silently incomplete. None of them
473	 * are safe to execute; report each as an error so the model can re-issue them.
474	 */
475	async function failToolCallsFromTruncatedMessage(
476		toolCalls: AgentToolCall[],
477		emit: AgentEventSink,
478	): Promise<ExecutedToolCallBatch> {
479		const messages: ToolResultMessage[] = [];
480		for (const toolCall of toolCalls) {
481			await emit({
482				type: "tool_execution_start",
483				toolCallId: toolCall.id,
484				toolName: toolCall.name,
485				args: toolCall.arguments,
486			});
487			const finalized: FinalizedToolCallOutcome = {
488				toolCall,
489				result: createErrorToolResult(
490					`Tool call "${toolCall.name}" was not executed: the response hit the output token limit, so its arguments may be truncated. Re-issue the tool call with complete arguments.`,
491				),
492				isError: true,
493			};
494			await emitToolExecutionEnd(finalized, emit);
495			const toolResultMessage = createToolResultMessage(finalized);
496			await emitToolResultMessage(toolResultMessage, emit);
497			messages.push(toolResultMessage);
498		}
499		return { messages, terminate: false };
500	}
501	
502	/**
503	 * Execute tool calls from an assistant message.
504	 */
505	async function executeToolCalls(
506		currentContext: AgentContext,
507		assistantMessage: AssistantMessage,
508		config: AgentLoopConfig,
509		signal: AbortSignal | undefined,
510		emit: AgentEventSink,
511	): Promise<ExecutedToolCallBatch> {
512		const toolCalls = assistantMessage.content.filter((c) => c.type === "toolCall");
513		const hasSequentialToolCall = toolCalls.some(
514			(tc) => currentContext.tools?.find((t) => t.name === tc.name)?.executionMode === "sequential",
515		);
516		if (config.toolExecution === "sequential" || hasSequentialToolCall) {
517			return executeToolCallsSequential(currentContext, assistantMessage, toolCalls, config, signal, emit);
518		}
519		return executeToolCallsParallel(currentContext, assistantMessage, toolCalls, config, signal, emit);
520	}
521	
522	type ExecutedToolCallBatch = {
523		messages: ToolResultMessage[];
524		terminate: boolean;
525	};
526	
527	async function executeToolCallsSequential(
528		currentContext: AgentContext,
529		assistantMessage: AssistantMessage,
530		toolCalls: AgentToolCall[],
531		config: AgentLoopConfig,
532		signal: AbortSignal | undefined,
533		emit: AgentEventSink,
534	): Promise<ExecutedToolCallBatch> {
535		const finalizedCalls: FinalizedToolCallOutcome[] = [];
536		const messages: ToolResultMessage[] = [];
537	
538		for (const toolCall of toolCalls) {
539			await emit({
540				type: "tool_execution_start",
541				toolCallId: toolCall.id,
542				toolName: toolCall.name,
543				args: toolCall.arguments,
544			});
545	
546			const preparation = await prepareToolCall(currentContext, assistantMessage, toolCall, config, signal);
547			let finalized: FinalizedToolCallOutcome;
548			if (preparation.kind === "immediate") {
549				finalized = {
550					toolCall,
551					result: preparation.result,
552					isError: preparation.isError,
553				};
554			} else {
555				const executed = await executePreparedToolCall(preparation, signal, emit);
556				finalized = await finalizeExecutedToolCall(
557					currentContext,
558					assistantMessage,
559					preparation,
560					executed,
561					config,
562					signal,
563				);
564			}
565	
566			await emitToolExecutionEnd(finalized, emit);
567			const toolResultMessage = createToolResultMessage(finalized);
568			await emitToolResultMessage(toolResultMessage, emit);
569			finalizedCalls.push(finalized);
570			messages.push(toolResultMessage);
571	
572			if (signal?.aborted) {
573				break;
574			}
575		}
576	
577		return {
578			messages,
579			terminate: shouldTerminateToolBatch(finalizedCalls),
580		};
581	}
582	
583	async function executeToolCallsParallel(
584		currentContext: AgentContext,
585		assistantMessage: AssistantMessage,
586		toolCalls: AgentToolCall[],
587		config: AgentLoopConfig,
588		signal: AbortSignal | undefined,
589		emit: AgentEventSink,
590	): Promise<ExecutedToolCallBatch> {
591		const finalizedCalls: FinalizedToolCallEntry[] = [];
592	
593		for (const toolCall of toolCalls) {
594			await emit({
595				type: "tool_execution_start",
596				toolCallId: toolCall.id,
597				toolName: toolCall.name,
598				args: toolCall.arguments,
599			});
600	
601			const preparation = await prepareToolCall(currentContext, assistantMessage, toolCall, config, signal);
602			if (preparation.kind === "immediate") {
603				const finalized = {
604					toolCall,
605					result: preparation.result,
606					isError: preparation.isError,
607				} satisfies FinalizedToolCallOutcome;
608				await emitToolExecutionEnd(finalized, emit);
609				finalizedCalls.push(finalized);
610				if (signal?.aborted) {
611					break;
612				}
613				continue;
614			}
615	
616			finalizedCalls.push(async () => {
617				if (signal?.aborted) {
618					const finalized = {
619						toolCall,
620						result: createErrorToolResult("Operation aborted"),
621						isError: true,
622					} satisfies FinalizedToolCallOutcome;
623					await emitToolExecutionEnd(finalized, emit);
624					return finalized;
625				}
626				const executed = await executePreparedToolCall(preparation, signal, emit);
627				const finalized = await finalizeExecutedToolCall(
628					currentContext,
629					assistantMessage,
630					preparation,
631					executed,
632					config,
633					signal,
634				);
635				await emitToolExecutionEnd(finalized, emit);
636				return finalized;
637			});
638			if (signal?.aborted) {
639				break;
640			}
641		}
642	
643		const orderedFinalizedCalls = await Promise.all(
644			finalizedCalls.map((entry) => (typeof entry === "function" ? entry() : Promise.resolve(entry))),
645		);
646		const messages: ToolResultMessage[] = [];
647		for (const finalized of orderedFinalizedCalls) {
648			const toolResultMessage = createToolResultMessage(finalized);
649			await emitToolResultMessage(toolResultMessage, emit);
650			messages.push(toolResultMessage);
651		}
652	
653		return {
654			messages,
655			terminate: shouldTerminateToolBatch(orderedFinalizedCalls),
656		};
657	}
658	
659	type PreparedToolCall = {
660		kind: "prepared";
661		toolCall: AgentToolCall;
662		tool: AgentTool<any>;
663		args: unknown;
664	};
665	
666	type ImmediateToolCallOutcome = {
667		kind: "immediate";
668		result: AgentToolResult<any>;
669		isError: boolean;
670	};
671	
672	type ExecutedToolCallOutcome = {
673		result: AgentToolResult<any>;
674		isError: boolean;
675	};
676	
677	type FinalizedToolCallOutcome = {
678		toolCall: AgentToolCall;
679		result: AgentToolResult<any>;
680		isError: boolean;
681	};
682	
683	type FinalizedToolCallEntry = FinalizedToolCallOutcome | (() => Promise<FinalizedToolCallOutcome>);
684	
685	function shouldTerminateToolBatch(finalizedCalls: FinalizedToolCallOutcome[]): boolean {
686		return finalizedCalls.length > 0 && finalizedCalls.every((finalized) => finalized.result.terminate === true);
687	}
688	
689	function prepareToolCallArguments(tool: AgentTool<any>, toolCall: AgentToolCall): AgentToolCall {
690		if (!tool.prepareArguments) {
691			return toolCall;
692		}
693		const preparedArguments = tool.prepareArguments(toolCall.arguments);
694		if (preparedArguments === toolCall.arguments) {
695			return toolCall;
696		}
697		return {
698			...toolCall,
699			arguments: preparedArguments as Record<string, any>,
700		};
701	}
702	
703	async function prepareToolCall(
704		currentContext: AgentContext,
705		assistantMessage: AssistantMessage,
706		toolCall: AgentToolCall,
707		config: AgentLoopConfig,
708		signal: AbortSignal | undefined,
709	): Promise<PreparedToolCall | ImmediateToolCallOutcome> {
710		const tool = currentContext.tools?.find((t) => t.name === toolCall.name);
711		if (!tool) {
712			return {
713				kind: "immediate",
714				result: createErrorToolResult(`Tool ${toolCall.name} not found`),
715				isError: true,
716			};
717		}
718	
719		try {
720			const preparedToolCall = prepareToolCallArguments(tool, toolCall);
721			const validatedArgs = validateToolArguments(tool, preparedToolCall);
722			if (config.beforeToolCall) {
723				const beforeResult = await config.beforeToolCall(
724					{
725						assistantMessage,
726						toolCall,
727						args: validatedArgs,
728						context: currentContext,
729					},
730					signal,
731				);
732				if (signal?.aborted) {
733					return {
734						kind: "immediate",
735						result: createErrorToolResult("Operation aborted"),
736						isError: true,
737					};
738				}
739				if (beforeResult?.block) {
740					const result = createErrorToolResult(beforeResult.reason || "Tool execution was blocked");
741					if (beforeResult.terminate === true) {
742						result.terminate = true;
743					}
744					return {
745						kind: "immediate",
746						result,
747						isError: true,
748					};
749				}
750			}
751			if (signal?.aborted) {
752				return {
753					kind: "immediate",
754					result: createErrorToolResult("Operation aborted"),
755					isError: true,
756				};
757			}
758			return {
759				kind: "prepared",
760				toolCall,
761				tool,
762				args: validatedArgs,
763			};
764		} catch (error) {
765			return {
766				kind: "immediate",
767				result: createErrorToolResult(error instanceof Error ? error.message : String(error)),
768				isError: true,
769			};
770		}
771	}
772	
773	async function executePreparedToolCall(
774		prepared: PreparedToolCall,
775		signal: AbortSignal | undefined,
776		emit: AgentEventSink,
777	): Promise<ExecutedToolCallOutcome> {
778		const updateEvents: Promise<void>[] = [];
779		let acceptingUpdates = true;
780	
781		try {
782			const result = await prepared.tool.execute(
783				prepared.toolCall.id,
784				prepared.args as never,
785				signal,
786				(partialResult) => {
787					if (!acceptingUpdates) return;
788					updateEvents.push(
789						Promise.resolve(
790							emit({
791								type: "tool_execution_update",
792								toolCallId: prepared.toolCall.id,
793								toolName: prepared.toolCall.name,
794								args: prepared.toolCall.arguments,
795								partialResult,
796							}),
797						),
798					);
799				},
800			);
801			acceptingUpdates = false;
802			await Promise.all(updateEvents);
803			return { result, isError: false };
804		} catch (error) {
805			acceptingUpdates = false;
806			await Promise.all(updateEvents);
807			return {
808				result: createErrorToolResult(error instanceof Error ? error.message : String(error)),
809				isError: true,
810			};
811		} finally {
812			acceptingUpdates = false;
813		}
814	}
815	
816	async function finalizeExecutedToolCall(
817		currentContext: AgentContext,
818		assistantMessage: AssistantMessage,
819		prepared: PreparedToolCall,
820		executed: ExecutedToolCallOutcome,
821		config: AgentLoopConfig,
822		signal: AbortSignal | undefined,
823	): Promise<FinalizedToolCallOutcome> {
824		let result = executed.result;
825		let isError = executed.isError;
826	
827		if (config.afterToolCall) {
828			try {
829				const afterResult = await config.afterToolCall(
830					{
831						assistantMessage,
832						toolCall: prepared.toolCall,
833						args: prepared.args,
834						result,
835						isError,
836						context: currentContext,
837					},
838					signal,
839				);
840				if (afterResult) {
841					result = {
842						...result,
843						content: afterResult.content ?? result.content,
844						details: afterResult.details ?? result.details,
845						usage: afterResult.usage ?? result.usage,
846						terminate: afterResult.terminate ?? result.terminate,
847					};
848					isError = afterResult.isError ?? isError;
849				}
850			} catch (error) {
851				result = createErrorToolResult(error instanceof Error ? error.message : String(error));
852				isError = true;
853			}
854		}
855	
856		return {
857			toolCall: prepared.toolCall,
858			result,
859			isError,
860		};
861	}
862	
863	function createErrorToolResult(message: string): AgentToolResult<any> {
864		return {
865			content: [{ type: "text", text: message }],
866			details: {},
867		};
868	}
869	
870	async function emitToolExecutionEnd(finalized: FinalizedToolCallOutcome, emit: AgentEventSink): Promise<void> {
871		await emit({
872			type: "tool_execution_end",
873			toolCallId: finalized.toolCall.id,
874			toolName: finalized.toolCall.name,
875			result: finalized.result,
876			isError: finalized.isError,
877		});
878	}
879	
880	function createToolResultMessage(finalized: FinalizedToolCallOutcome): ToolResultMessage {
881		return {
882			role: "toolResult",
883			toolCallId: finalized.toolCall.id,
884			toolName: finalized.toolCall.name,
885			// Untyped tools (JS extensions) can return results without content; normalize
886			// so the null never enters session history or provider payloads.
887			content: finalized.result.content ?? [],
888			details: finalized.result.details,
889			usage: finalized.result.usage,
890			isError: finalized.isError,
891			timestamp: Date.now(),
892		};
893	}
894	
895	async function emitToolResultMessage(toolResultMessage: ToolResultMessage, emit: AgentEventSink): Promise<void> {
896		await emit({ type: "message_start", message: toolResultMessage });
897		await emit({ type: "message_end", message: toolResultMessage });
898	}
