243			this.prepareNextTurnWithContext = runtimeOptions.prepareNextTurnWithContext;
244			this.steeringQueue = new PendingMessageQueue(runtimeOptions.steeringMode ?? "one-at-a-time");
245			this.followUpQueue = new PendingMessageQueue(runtimeOptions.followUpMode ?? "one-at-a-time");
246			this.sessionId = runtimeOptions.sessionId;
247			this.thinkingBudgets = runtimeOptions.thinkingBudgets;
248			this.transport = runtimeOptions.transport ?? "auto";
249			this.maxRetryDelayMs = runtimeOptions.maxRetryDelayMs;
250			this.toolExecution = runtimeOptions.toolExecution ?? "parallel";
251		}
252	
253		/**
254		 * Subscribe to agent lifecycle events.
255		 *
256		 * Listener promises are awaited in subscription order and are included in
257		 * the current run's settlement. Listeners also receive the active abort
258		 * signal for the current run.
259		 *
260		 * `agent_end` is the final emitted event for a run, but the agent does not
261		 * become idle until all awaited listeners for that event have settled.
262		 */
263		subscribe(listener: (event: AgentEvent, signal: AbortSignal) => Promise<void> | void): () => void {
264			this.listeners.add(listener);
265			return () => this.listeners.delete(listener);
266		}
267	
268		/**
269		 * Current agent state.
270		 *
271		 * Assigning `state.tools` or `state.messages` copies the provided top-level array.
272		 */
273		get state(): AgentState {
274			return this._state;
275		}
276	
277		/** Controls how queued steering messages are drained. */
278		set steeringMode(mode: QueueMode) {
279			this.steeringQueue.mode = mode;
280		}
281	
282		get steeringMode(): QueueMode {
283			return this.steeringQueue.mode;
284		}
285	
286		/** Controls how queued follow-up messages are drained. */
287		set followUpMode(mode: QueueMode) {
288			this.followUpQueue.mode = mode;
289		}
290	
291		get followUpMode(): QueueMode {
292			return this.followUpQueue.mode;
293		}
294	
295		/** Queue a message to be injected after the current assistant turn finishes. */
296		steer(message: AgentMessage): void {
297			this.steeringQueue.enqueue(message);
298		}
299	
300		/** Queue a message to run only after the agent would otherwise stop. */
301		followUp(message: AgentMessage): void {
302			this.followUpQueue.enqueue(message);
303		}
304	
305		/** Remove all queued steering messages. */
306		clearSteeringQueue(): void {
307			this.steeringQueue.clear();
308		}
309	
310		/** Remove all queued follow-up messages. */
311		clearFollowUpQueue(): void {
312			this.followUpQueue.clear();
313		}
314	
315		/** Remove all queued steering and follow-up messages. */
316		clearAllQueues(): void {
317			this.clearSteeringQueue();
318			this.clearFollowUpQueue();
319		}
320	
321		/** Returns true when either queue still contains pending messages. */
322		hasQueuedMessages(): boolean {
323			return this.steeringQueue.hasItems() || this.followUpQueue.hasItems();
324		}
325	
326		/** Preview the messages selected for the next turn without consuming them. */
327		peekQueuedMessages(): AgentMessage[] {
328			const steering = this.steeringQueue.peek();
329			return steering.length > 0 ? steering : this.followUpQueue.peek();
330		}
331	
332		/** Active abort signal for the current run, if any. */
333		get signal(): AbortSignal | undefined {
334			return this.activeRun?.abortController.signal;
335		}
336	
337		/** Abort the current run, if one is active. */
338		abort(): void {
339			this.activeRun?.abortController.abort();
340		}
341	
342		/**
343		 * Resolve when the current run and all awaited event listeners have finished.
344		 *
345		 * This resolves after `agent_end` listeners settle.
346		 */
347		waitForIdle(): Promise<void> {
348			return this.activeRun?.promise ?? Promise.resolve();
349		}
350	
351		/** Clear conversation state and queues while retaining the replayed prompt/tool baseline. */
352		reset(): void {
353			if (this.activeRun) {
354				throw new Error("Agent is already processing. Wait for completion before resetting.");
355			}
356	
357			const baseline = getCurrentSystemMessage(this._state.messages);
358			this._state.messages = baseline ? [baseline] : [];
359			this._state.isStreaming = false;
360			this._state.streamingMessage = undefined;
361			this._state.pendingToolCalls = new Set<string>();
362			this._state.errorMessage = undefined;
363			this.clearFollowUpQueue();
364			this.clearSteeringQueue();
365		}
366	
367		/** Start a new prompt from text, a single message, or a batch of messages. */
368		async prompt(message: AgentMessage | AgentMessage[]): Promise<void>;
369		async prompt(input: string, images?: ImageContent[]): Promise<void>;
370		async prompt(input: string | AgentMessage | AgentMessage[], images?: ImageContent[]): Promise<void> {
371			if (this.activeRun) {
372				throw new Error(
373					"Agent is already processing a prompt. Use steer() or followUp() to queue messages, or wait for completion.",
374				);
375			}
376			const messages = this.normalizePromptInput(input, images);
377			await this.runPromptMessages(messages);
378		}
379	
380		/** Continue from the current transcript. The last message must be a user or tool-result message. */
381		async continue(): Promise<void> {
382			if (this.activeRun) {
383				throw new Error("Agent is already processing. Wait for completion before continuing.");
384			}
385	
386			const lastMessage = this._state.messages[this._state.messages.length - 1];
387			if (!lastMessage || this._state.messages.every((message) => message.role === "system")) {
388				throw new Error("No messages to continue from");
389			}
390	
391			if (lastMessage.role === "assistant") {
392				const queuedSteering = this.steeringQueue.drain();
393				if (queuedSteering.length > 0) {
394					await this.runPromptMessages(queuedSteering, { skipInitialSteeringPoll: true });
395					return;
396				}
397	
398				const queuedFollowUps = this.followUpQueue.drain();
399				if (queuedFollowUps.length > 0) {
400					await this.runPromptMessages(queuedFollowUps);
401					return;
402				}
403	
404				throw new Error("Cannot continue from message role: assistant");
405			}
406	
407			await this.runContinuation();
408		}
409	
410		private normalizePromptInput(
411			input: string | AgentMessage | AgentMessage[],
412			images?: ImageContent[],
413		): AgentMessage[] {
414			if (Array.isArray(input)) {
415				return input;
416			}
417	
418			if (typeof input !== "string") {
419				return [input];
420			}
421	
422			const content: Array<TextContent | ImageContent> = [{ type: "text", text: input }];
423			if (images && images.length > 0) {
424				content.push(...images);
425			}
426			return [{ role: "user", content, timestamp: Date.now() }];
427		}
428	
429		private async runPromptMessages(
430			messages: AgentMessage[],
431			options: { skipInitialSteeringPoll?: boolean } = {},
432		): Promise<void> {
433			await this.runWithLifecycle(async (signal) => {
434				await runAgentLoop(
435					messages,
436					this.createContextSnapshot(),
437					this.createLoopConfig(options),
438					(event) => this.processEvents(event),
439					signal,
440					this.streamFunction,
441				);
442			});
443		}
444	
445		private async runContinuation(): Promise<void> {
446			await this.runWithLifecycle(async (signal) => {
447				await runAgentLoopContinue(
448					this.createContextSnapshot(),
449					this.createLoopConfig(),
450					(event) => this.processEvents(event),
451					signal,
452					this.streamFunction,
453				);
454			});
455		}
456	
457		private createContextSnapshot(): AgentContext {
458			return {
459				messages: this._state.messages.slice(),
460				tools: this._state.tools.slice(),
461			};
462		}
463	
464		private createLoopConfig(options: { skipInitialSteeringPoll?: boolean } = {}): AgentLoopConfig {
465			let skipInitialSteeringPoll = options.skipInitialSteeringPoll === true;
466			return {
467				model: this._state.model,
468				reasoning: this._state.thinkingLevel === "off" ? undefined : this._state.thinkingLevel,
469				sessionId: this.sessionId,
470				onPayload: this.onPayload,
471				onResponse: this.onResponse,
472				transport: this.transport,
473				thinkingBudgets: this.thinkingBudgets,
474				maxRetryDelayMs: this.maxRetryDelayMs,
475				toolExecution: this.toolExecution,
476				beforeToolCall: this.beforeToolCall,
477				afterToolCall: this.afterToolCall,
478				finishTurn: this.finishTurn,
479				prepareRequest: this.prepareRequest,
480				prepareNextTurn:
481					this.prepareNextTurnWithContext || this.prepareNextTurn
482						? async (context) => {
483								if (this.prepareNextTurnWithContext) {
484									return await this.prepareNextTurnWithContext(context, this.signal);
485								}
486								return await this.prepareNextTurn?.(this.signal);
487							}
488						: undefined,
489				convertToLlm: this.convertToLlm,
490				transformContext: this.transformContext,
491				getApiKey: this.getApiKey,
492				getSteeringMessages: async () => {
493					if (skipInitialSteeringPoll) {
494						skipInitialSteeringPoll = false;
495						return [];
496					}
497					return this.steeringQueue.drain();
498				},
499				getFollowUpMessages: async () => this.followUpQueue.drain(),
500			};
501		}
502	
503		private async runWithLifecycle(executor: (signal: AbortSignal) => Promise<void>): Promise<void> {
504			if (this.activeRun) {
505				throw new Error("Agent is already processing.");
506			}
507	
508			const abortController = new AbortController();
509			let resolvePromise = () => {};
510			const promise = new Promise<void>((resolve) => {
511				resolvePromise = resolve;
512			});
513			this.activeRun = { promise, resolve: resolvePromise, abortController };
514	
515			this._state.isStreaming = true;
516			this._state.streamingMessage = undefined;
517			this._state.errorMessage = undefined;
518	
519			try {
520				await executor(abortController.signal);
521			} catch (error) {
522				await this.handleRunFailure(error, abortController.signal.aborted);
523			} finally {
524				this.finishRun();
525			}
526		}
527	
528		private async handleRunFailure(error: unknown, aborted: boolean): Promise<void> {
529			const failureMessage = {
530				role: "assistant",
531				content: [{ type: "text", text: "" }],
532				api: this._state.model.api,
533				provider: this._state.model.provider,
534				model: this._state.model.id,
535				usage: EMPTY_USAGE,
536				stopReason: aborted ? "aborted" : "error",
537				errorMessage: error instanceof Error ? error.message : String(error),
538				timestamp: Date.now(),
539			} satisfies AgentMessage;
540			await this.processEvents({ type: "message_start", message: failureMessage });
541			await this.processEvents({ type: "message_end", message: failureMessage });
542			await this.processEvents({ type: "turn_end", message: failureMessage, toolResults: [] });
543			await this.processEvents({ type: "agent_end", messages: [failureMessage] });
544		}
545	
546		private finishRun(): void {
547			this._state.isStreaming = false;
548			this._state.streamingMessage = undefined;
549			this._state.pendingToolCalls = new Set<string>();
550			this.activeRun?.resolve();
551			this.activeRun = undefined;
552		}
553	
554		/**
555		 * Reduce internal state for a loop event, then await listeners.
556		 *
557		 * `agent_end` only means no further loop events will be emitted. The run is
558		 * considered idle later, after all awaited listeners for `agent_end` finish
559		 * and `finishRun()` clears runtime-owned state.
560		 */
561		private async processEvents(event: AgentEvent): Promise<void> {
562			switch (event.type) {
563				case "message_start":
564					this._state.streamingMessage = event.message;
565					break;
566	
567				case "message_update":
568					this._state.streamingMessage = event.message;
569					break;
570	
571				case "message_end":
572					this._state.streamingMessage = undefined;
573					this._state.messages.push(event.message);
574					break;
575	
576				case "tool_execution_start": {
577					const pendingToolCalls = new Set(this._state.pendingToolCalls);
578					pendingToolCalls.add(event.toolCallId);
579					this._state.pendingToolCalls = pendingToolCalls;
580					break;
581				}
582	
583				case "tool_execution_end": {
584					const pendingToolCalls = new Set(this._state.pendingToolCalls);
585					pendingToolCalls.delete(event.toolCallId);
586					this._state.pendingToolCalls = pendingToolCalls;
587					break;
588				}
589	
590				case "turn_end":
591					if (event.message.role === "assistant" && event.message.errorMessage) {
592						this._state.errorMessage = event.message.errorMessage;
593					}
594					break;
595	
596				case "agent_end":
597					this._state.streamingMessage = undefined;
598					break;
599			}
600	
601			const signal = this.activeRun?.abortController.signal;
602			if (!signal) {
603				throw new Error("Agent listener invoked outside active run");
604			}
605			for (const listener of this.listeners) {
606				await listener(event, signal);
607			}
608		}
609	}
