34	export type NormalizedBuildSystemPromptOptions = BuildSystemPromptOptions & {
35		selectedTools: string[];
36		toolSnippets: Record<string, string>;
37		toolGuidelines: Record<string, string[]>;
38		promptGuidelines: string[];
39		appendSystemPrompt: string;
