52	const SYSTEM_PROMPT_SECTION_NAME = /^[a-z][a-z0-9_-]*$/;
53	/** Normalize prompt input into the mutable, collection-complete shape exposed to extensions. */
54	export function normalizeBuildSystemPromptOptions(input: BuildSystemPromptOptions): NormalizedBuildSystemPromptOptions {
55		return {
56			customPrompt: input.customPrompt,
57			forceSystemPrompt: input.forceSystemPrompt,
58			selectedTools: [...(input.selectedTools ?? ["read", "bash", "edit", "write"])],
59			toolSnippets: { ...(input.toolSnippets ?? {}) },
60			toolGuidelines: Object.fromEntries(
