83		toolGuidelines: Record<string, string[]>,
84		promptGuidelines: string[],
85	): string {
86		const rules: string[] = [];
87		const seen = new Set<string>();
88		const addRule = (rule: string): void => {
89			const normalized = rule.trim();
90			if (!normalized || seen.has(normalized)) return;
91			seen.add(normalized);
92			rules.push(normalized);
93		};
