101		if ((hasBash || hasPowerShell) && !hasGrep && !hasFind && !hasLs) {
102			if (hasBash && hasPowerShell) {
103				addRule("Use bash or PowerShell for file operations like listing, searching, and finding files");
104			} else if (hasPowerShell) {
105				addRule("Use PowerShell for file operations like listing, searching, and finding files");
106			} else {
107				addRule("Use bash for file operations like ls, rg, find");
108			}
109		}
110	
111		for (const name of selectedTools) {
112			for (const rule of toolGuidelines[name] ?? []) addRule(rule);
113		}
114		for (const rule of promptGuidelines) addRule(rule);
115		addRule("Be concise in your responses");
116		addRule("Show file paths clearly when working with files");
117		return rules.map((rule) => `- ${rule}`).join("\n");
118	}
