120	/** Build the ordered, independently replaceable sections of the structured system prompt. */
121	export function buildSystemPromptSections(input: BuildSystemPromptOptions): SystemPromptSections {
122		const options = normalizeBuildSystemPromptOptions(input);
123		const {
124			customPrompt,
125			selectedTools,
126			toolSnippets,
127			toolGuidelines,
128			promptGuidelines,
129			appendSystemPrompt,
130			sections: customSections,
131			cwd,
132			contextFiles,
133			skills,
134		} = options;
135	
136		for (const name of Object.keys(customSections)) {
137			if (!SYSTEM_PROMPT_SECTION_NAME.test(name) || name === "preamble") {
138				throw new Error(`Invalid system prompt section name: ${name}`);
139			}
140		}
141	
142		const promptSections: Record<string, string> = {};
143		if (customPrompt) {
144			promptSections.preamble = customPrompt;
145		} else {
146			promptSections.preamble =
147				"You are an expert coding assistant operating inside pi, a coding agent harness. You help users by reading files, executing commands, editing code, and writing new files.";
148			const visibleTools = selectedTools.filter((name) => !!toolSnippets[name]);
149			const tools =
