151			promptSections.tools = `${tools}\n\nIn addition to the tools above, you may have access to other custom tools depending on the project.`;
152			promptSections.rules = buildRules(selectedTools, toolGuidelines, promptGuidelines);
153			promptSections.docs = `Pi documentation (read only when the user asks about pi itself, its SDK, extensions, themes, skills, or TUI):
154	- Main documentation: ${getReadmePath()}
155	- Additional docs: ${getDocsPath()}
156	- Examples: ${getExamplesPath()} (extensions, custom tools, SDK)
157	- When reading pi docs or examples, resolve docs/... under Additional docs and examples/... under Examples, not the current working directory
158	- When asked about: extensions (docs/extensions.md, examples/extensions/), themes (docs/themes.md), skills (docs/skills.md), prompt templates (docs/prompt-templates.md), TUI components (docs/tui.md), keybindings (docs/keybindings.md), SDK integrations (docs/sdk.md), custom providers (docs/custom-provider.md), adding models (docs/models.md), pi packages (docs/packages.md), environment variables (docs/environment-variables.md)
159	- When working on pi topics, read the docs and examples, and follow .md cross-references before implementing
160	- Always read pi .md files completely and follow links to related docs (e.g., tui.md for TUI API details)`;
161		}
162	
163		if (appendSystemPrompt) promptSections.addendum = appendSystemPrompt;
164		if (contextFiles.length > 0) promptSections.project_context = renderProjectContext(contextFiles);
165		const skillFileReadTool = (["read", "bash"] as const).find((tool) => selectedTools.includes(tool));
166		if (skillFileReadTool && skills.length > 0) {
167			const skillsPrompt = formatSkillsForPrompt(skills, skillFileReadTool).trim();
168			if (skillsPrompt) promptSections.skills = skillsPrompt;
169		}
170		promptSections.cwd = cwd.replace(/\\/g, "/");
171		for (const [name, content] of Object.entries(customSections)) {
172			if (content) promptSections[name] = content;
173		}
174	
175		const sections: SystemPromptSections = { preamble: promptSections.preamble };
176		for (const [name, content] of Object.entries(promptSections)) {
177			if (name !== "preamble") sections[name] = `<${name}>\n${content}\n</${name}>`;
178		}
179		return sections;
180	}
