182	/**
183	 * The complete prompt state for `input`. A forced prompt is opaque and lives in `content`
184	 * with no sections; otherwise `content` is empty and the structured sections carry the prompt.
185	 */
186	export function buildSystemPromptState(input: BuildSystemPromptOptions): {
187		content: string;
188		sections?: SystemPromptSections;
189	} {
190		if (input.forceSystemPrompt !== undefined) return { content: input.forceSystemPrompt };
191		return { content: "", sections: buildSystemPromptSections(input) };
192	}
193	
194	/** Build the system prompt text, rendered exactly as the transcript's system message replays it. */
195	export function buildSystemPrompt(input: BuildSystemPromptOptions): string {
196		return getSystemMessageText({ role: "system", ...buildSystemPromptState(input), timestamp: 0 });
197	}
198	
199	/**
200	 * Diff the sections the model currently has (replayed from the transcript, so never null)
201	 * against the desired ones. Returns a `SystemMessage.sections` patch, or undefined when
202	 * nothing changed.
203	 */
204	export function diffSystemPromptSections(
205		previous: Record<string, string | null>,
206		current: SystemPromptSections,
207	): Record<string, string | null> | undefined {
208		const patch: Record<string, string | null> = {};
209		for (const [name, text] of Object.entries(current)) {
210			if (previous[name] !== text) patch[name] = text;
211		}
212		for (const name of Object.keys(previous)) {
213			if (current[name] === undefined) patch[name] = null;
214		}
215		return Object.keys(patch).length > 0 ? patch : undefined;
216	}
