910	function createClient(
911		model: Model<"anthropic-messages">,
912		apiKey: string | undefined,
913		optionsHeaders?: ProviderHeaders,
914		fetch?: typeof globalThis.fetch,
915		dynamicHeaders?: Record<string, string>,
916		sessionId?: string,
917	): { client: Anthropic; isOAuthToken: boolean } {
918		// Copilot: Bearer auth.
919		if (model.provider === "github-copilot") {
920			const client = new Anthropic({
921				apiKey: null,
922				authToken: apiKey ?? null,
923				baseURL: model.baseUrl,
924				dangerouslyAllowBrowser: true,
925				fetch,
926				defaultHeaders: mergeClientHeaders(
927					{
928						accept: "application/json",
929						"anthropic-dangerous-direct-browser-access": "true",
930					},
931					model.headers,
932					dynamicHeaders,
933					optionsHeaders,
934				),
935			});
936	
937			return { client, isOAuthToken: false };
938		}
939	
940		// OAuth: Bearer auth, Claude Code identity headers
941		if (apiKey && isOAuthToken(apiKey)) {
942			const client = new Anthropic({
943				apiKey: null,
944				authToken: apiKey,
945				baseURL: model.baseUrl,
946				dangerouslyAllowBrowser: true,
947				fetch,
948				defaultHeaders: mergeClientHeaders(
949					{
950						accept: "application/json",
951						"anthropic-dangerous-direct-browser-access": "true",
952						"user-agent": `claude-cli/${claudeCodeVersion}`,
953						"x-app": "cli",
954					},
955					model.headers,
956					optionsHeaders,
957				),
958			});
959	
960			return { client, isOAuthToken: true };
961		}
962	
963		// API key or header-owned auth.
964		const compat = getAnthropicCompat(model);
965		const sessionAffinityHeaders: ProviderHeaders = {};
966		if (sessionId && compat.sendSessionAffinityHeaders) {
967			const header = compat.sessionAffinityFormat === "openrouter" ? "x-session-id" : "x-session-affinity";
968			sessionAffinityHeaders[header] = sessionId;
969		}
970		const defaultHeaders = mergeClientHeaders(
971			{
972				accept: "application/json",
973				"anthropic-dangerous-direct-browser-access": "true",
974			},
975			sessionAffinityHeaders,
976			model.headers,
977			optionsHeaders,
978		);
979		const client = new Anthropic({
980			apiKey: apiKey ?? null,
981			authToken: null,
982			baseURL: model.baseUrl,
983			dangerouslyAllowBrowser: true,
984			fetch,
985			defaultHeaders,
986		});
987	
988		return { client, isOAuthToken: false };
989	}
