41	export interface CreateAgentSessionOptions {
42		/** Working directory for project-local discovery. Default: process.cwd() */
43		cwd?: string;
44		/** Global config directory. Default: ~/.pi/agent */
45		agentDir?: string;
46	
47		/** Canonical model/auth runtime. Defaults to a runtime using agentDir/auth.json and models.json. */
48		modelRuntime?: ModelRuntime;
49	
50		/** Model to use. Default: from settings, else first available */
51		model?: Model<any>;
52		/** Thinking level. Default: from settings, else 'medium' (clamped to model capabilities) */
53		thinkingLevel?: ThinkingLevel;
54		/** Models available for cycling (Ctrl+P in interactive mode) */
55		scopedModels?: Array<{ model: Model<any>; thinkingLevel?: ThinkingLevel }>;
56	
57		/**
58		 * Optional default tool suppression mode when no explicit allowlist is provided.
59		 *
60		 * - "all": start with no tools enabled
61		 * - "builtin": disable the default built-in tools (read, bash, edit, write)
62		 *   but keep extension/custom tools enabled
63		 */
64		noTools?: "all" | "builtin";
65		/**
66		 * Optional allowlist of tool names.
67		 *
68		 * When omitted, pi uses the `defaultTools` setting for the initial built-in
69		 * selection when configured. Otherwise it enables the default built-in tools
70		 * (read, bash, edit, write). Extension/custom tools remain enabled unless
71		 * `noTools` changes that default. When provided, only the listed tool names are
72		 * enabled.
73		 */
74		tools?: string[];
75		/** Optional denylist of tool names to disable. Applies after `tools` when both are provided. */
76		excludeTools?: string[];
77		/** Custom tools to register (in addition to built-in tools). */
78		customTools?: ToolDefinition[];
79	
80		/** Resource loader. When omitted, DefaultResourceLoader is used. */
81		resourceLoader?: ResourceLoader;
82	
83		/** Session manager. Default: SessionManager.create(cwd) */
84		sessionManager?: SessionManager;
85	
86		/** Settings manager. Default: SettingsManager.create(cwd, agentDir) */
87		settingsManager?: SettingsManager;
88		/** Session start event metadata for extension runtime startup. */
89		sessionStartEvent?: SessionStartEvent;
90	}
