93	export interface CreateAgentSessionResult {
94		/** The created session */
95		session: AgentSession;
96		/** Extensions result (for UI context setup in interactive mode) */
97		extensionsResult: LoadExtensionsResult;
98		/** Warning if session was restored with a different model than saved */
99		modelFallbackMessage?: string;
100	}
