136	function getDefaultAgentDir(): string {
137		return getAgentDir();
138	}
139	
140	/**
141	 * Create an AgentSession with the specified options.
142	 *
143	 * @example
144	 * ```typescript
145	 * // Minimal - uses defaults
146	 * const { session } = await createAgentSession();
147	 *
148	 * // With explicit model
149	 * import { getModel } from '@earendil-works/pi-ai';
150	 * const { session } = await createAgentSession({
151	 *   model: getModel('anthropic', 'claude-opus-4-5'),
152	 *   thinkingLevel: 'high',
153	 * });
154	 *
155	 * // Continue previous session
156	 * const { session, modelFallbackMessage } = await createAgentSession({
157	 *   continueSession: true,
158	 * });
159	 *
160	 * // Full control
161	 * const loader = new DefaultResourceLoader({
162	 *   cwd: process.cwd(),
163	 *   agentDir: getAgentDir(),
164	 *   settingsManager: SettingsManager.create(),
165	 * });
166	 * await loader.reload();
167	 * const { session } = await createAgentSession({
168	 *   model: myModel,
169	 *   tools: ["read", "bash"],
170	 *   resourceLoader: loader,
171	 *   sessionManager: SessionManager.inMemory(),
172	 * });
173	 * ```
174	 */
175	export async function createAgentSession(options: CreateAgentSessionOptions = {}): Promise<CreateAgentSessionResult> {
176		const cwd = resolvePath(options.cwd ?? options.sessionManager?.getCwd() ?? process.cwd());
177		const agentDir = options.agentDir ? resolvePath(options.agentDir) : getDefaultAgentDir();
178		let resourceLoader = options.resourceLoader;
179	
180		const authPath = options.agentDir ? join(agentDir, "auth.json") : undefined;
181		const modelsPath = options.agentDir ? join(agentDir, "models.json") : undefined;
182		const modelRuntime = options.modelRuntime ?? (await ModelRuntime.create({ authPath, modelsPath }));
183	
184		const settingsManager = options.settingsManager ?? SettingsManager.create(cwd, agentDir);
185		const sessionManager = options.sessionManager ?? SessionManager.create(cwd, getDefaultSessionDir(cwd, agentDir));
186	
187		if (!resourceLoader) {
188			resourceLoader = new DefaultResourceLoader({ cwd, agentDir, settingsManager });
189			await resourceLoader.reload();
190			time("resourceLoader.reload");
191		}
192	
193		// Check if session has existing data to restore
194		const existingSession = sessionManager.buildSessionContext();
195		const hasExistingSession = existingSession.messages.length > 0;
196		const hasThinkingEntry = sessionManager.getBranch().some((entry) => entry.type === "thinking_level_change");
197	
198		let model = options.model;
199		let modelFallbackMessage: string | undefined;
200	
201		// If session has data, try to restore model from it
202		if (!model && hasExistingSession && existingSession.model) {
203			const restoredModel = modelRuntime.getModel(existingSession.model.provider, existingSession.model.modelId);
204			if (restoredModel && modelRuntime.hasConfiguredAuth(restoredModel.provider)) {
205				model = restoredModel;
206			}
207			if (!model) {
208				modelFallbackMessage = `Could not restore model ${existingSession.model.provider}/${existingSession.model.modelId}`;
209			}
210		}
211	
212		// If still no model, use findInitialModel (checks settings default, then provider defaults)
213		if (!model) {
214			const result = await findInitialModel({
215				scopedModels: [],
216				isContinuing: hasExistingSession,
217				defaultProvider: settingsManager.getDefaultProvider(),
218				defaultModelId: settingsManager.getDefaultModel(),
219				defaultThinkingLevel: settingsManager.getDefaultThinkingLevel(),
220				modelThinkingLevels: settingsManager.getAllModelThinkingLevels(),
221				modelRuntime,
222			});
223			model = result.model;
224			if (!model) {
225				modelFallbackMessage = formatNoModelsAvailableMessage();
226			} else if (modelFallbackMessage) {
227				modelFallbackMessage += `. Using ${model.provider}/${model.id}`;
228			}
229		}
230	
231		let thinkingLevel = options.thinkingLevel;
232	
233		// If session has data, restore thinking level from it
234		if (thinkingLevel === undefined && hasExistingSession) {
235			thinkingLevel = hasThinkingEntry
236				? (existingSession.thinkingLevel as ThinkingLevel)
237				: (settingsManager.getDefaultThinkingLevel() ?? DEFAULT_THINKING_LEVEL);
238		}
239	
240		// Fall back to per-model override, then global default
241		if (thinkingLevel === undefined && model) {
242			const perModel = settingsManager.getModelThinkingLevel(model.provider, model.id);
243			if (perModel) {
244				thinkingLevel = perModel;
245			}
246		}
247		if (thinkingLevel === undefined) {
248			thinkingLevel = settingsManager.getDefaultThinkingLevel() ?? DEFAULT_THINKING_LEVEL;
249		}
250	
251		// Clamp to model capabilities
252		if (!model) {
253			thinkingLevel = "off";
254		} else {
255			thinkingLevel = clampThinkingLevel(model, thinkingLevel) as ThinkingLevel;
256		}
257	
258		const defaultActiveToolNames: ToolName[] = ["read", "bash", "edit", "write"];
259		const configuredDefaultToolNames = settingsManager.getDefaultTools();
260		const allowedToolNames = options.tools ?? (options.noTools === "all" ? [] : undefined);
261		const excludedToolNames = options.excludeTools;
262		const excludedToolNameSet = excludedToolNames ? new Set(excludedToolNames) : undefined;
263		const initialActiveToolNames = (
264			options.tools ?? (options.noTools ? [] : (configuredDefaultToolNames ?? defaultActiveToolNames))
265		).filter((name) => !excludedToolNameSet?.has(name));
266	
267		// Create convertToLlm wrapper that filters images if blockImages is enabled (defense-in-depth)
268		const convertToLlmWithBlockImages = (messages: AgentMessage[]): Message[] => {
269			const converted = convertToLlm(messages);
270			// Check setting dynamically so mid-session changes take effect
271			if (!settingsManager.getBlockImages()) {
272				return converted;
273			}
274			// Filter out ImageContent from all messages, replacing with text placeholder
275			return converted.map((msg) => {
276				if (msg.role === "user" || msg.role === "toolResult") {
277					const content = msg.content;
278					if (Array.isArray(content)) {
279						const hasImages = content.some((c) => c.type === "image");
280						if (hasImages) {
281							const filteredContent = content
282								.map((c) =>
283									c.type === "image" ? { type: "text" as const, text: "Image reading is disabled." } : c,
284								)
285								.filter(
286									(c, i, arr) =>
287										// Dedupe consecutive "Image reading is disabled." texts
288										!(
289											c.type === "text" &&
290											c.text === "Image reading is disabled." &&
291											i > 0 &&
292											arr[i - 1].type === "text" &&
293											(arr[i - 1] as { type: "text"; text: string }).text === "Image reading is disabled."
294										),
295								);
296							return { ...msg, content: filteredContent };
297						}
298					}
299				}
300				return msg;
301			});
302		};
303	
304		const extensionRunnerRef: { current?: ExtensionRunner } = {};
305		const cacheWarmer = new CacheWarmer(
306			modelRuntime,
307			sessionManager,
308			() => settingsManager.getCacheWarmingMode(),
309			async (event) => extensionRunnerRef.current?.emitCacheWarmingDecision(event) ?? event.action,
310		);
311		const buildRequestOptions = (
312			requestModel: Model<any>,
313			options: ModelsSimpleStreamOptions = {},
314		): ModelsSimpleStreamOptions => {
315			const providerRetrySettings = settingsManager.getProviderRetrySettings();
316			const httpIdleTimeoutMs = settingsManager.getHttpIdleTimeoutMs();
317			const effectiveTimeoutMs = httpIdleTimeoutMs === 0 ? 2147483647 : httpIdleTimeoutMs;
318			const headerRunner = extensionRunnerRef.current;
319			return {
320				...options,
321				timeoutMs: options.timeoutMs ?? providerRetrySettings.timeoutMs ?? effectiveTimeoutMs,
322				websocketConnectTimeoutMs: options.websocketConnectTimeoutMs ?? settingsManager.getWebSocketConnectTimeoutMs(),
323				maxRetries: options.maxRetries ?? providerRetrySettings.maxRetries,
324				maxRetryDelayMs: options.maxRetryDelayMs ?? providerRetrySettings.maxRetryDelayMs,
325				transformHeaders: async (requestHeaders) => {
326					const headers = mergeProviderAttributionHeaders(
327						requestModel,
328						settingsManager,
329						options.sessionId,
330						requestHeaders,
331					);
332					return headerRunner?.hasHandlers("before_provider_headers")
333						? headerRunner.emitBeforeProviderHeaders(headers ?? {})
334						: (headers ?? {});
335				},
336			};
337		};
338		const cacheContextIsCurrent = (requestModel: Model<any>) => {
339			const messages = agent.state.messages;
340			return () => {
341				const currentModel = agent.state.model;
342				const currentMessages = agent.state.messages;
343				return (
344					currentModel.provider === requestModel.provider &&
345					currentModel.id === requestModel.id &&
346					messages.length <= currentMessages.length &&
347					messages.every((message, index) => currentMessages[index] === message)
348				);
349			};
350		};
351		const transformProviderPayload = async (payload: unknown) => {
352			const runner = extensionRunnerRef.current;
353			if (!runner?.hasHandlers("before_provider_request")) return payload;
354			return runner.emitBeforeProviderRequest(payload);
355		};
356		const handleProviderResponse: NonNullable<ModelsSimpleStreamOptions["onResponse"]> = async (response) => {
357			const runner = extensionRunnerRef.current;
358			if (!runner?.hasHandlers("after_provider_response")) return;
359			await runner.emit({
360				type: "after_provider_response",
361				status: response.status,
362				headers: response.headers,
363			});
364		};
365	
366		const agent = new Agent({
367			initialState: {
368				systemPrompt: "",
369				model,
370				thinkingLevel,
371				tools: [],
372				messages: existingSession.messages,
373			},
374			convertToLlm: convertToLlmWithBlockImages,
375			streamFn: async (model, context, options) => {
376				const requestOptions = buildRequestOptions(model, options);
377				// Compaction and summaries use their own routing ids; only session requests
378				// replace the cache entry, so warming restarts from them. Keep warming while
379				// the current transcript still extends the request's prefix. Agent state may
380				// shallow-copy the messages array or refresh the model object without changing
381				// the provider request, so top-level object identity is not a valid cache key.
382				if (options?.sessionId === sessionManager.getSessionId()) {
383					cacheWarmer.start({ model, context, options: requestOptions }, cacheContextIsCurrent(model));
384				}
385				return modelRuntime.streamSimple(model, context, requestOptions);
386			},
387			onPayload: transformProviderPayload,
388			onResponse: handleProviderResponse,
389			sessionId: sessionManager.getSessionId(),
390			transformContext: async (messages) => {
391				const runner = extensionRunnerRef.current;
392				if (!runner) return messages;
393				return runner.emitContext(messages);
394			},
395			steeringMode: settingsManager.getSteeringMode(),
396			followUpMode: settingsManager.getFollowUpMode(),
397			transport: settingsManager.getTransport(),
398			thinkingBudgets: settingsManager.getThinkingBudgets(),
399			maxRetryDelayMs: settingsManager.getProviderRetrySettings().maxRetryDelayMs,
400		});
401	
402		// Restore missing settings metadata for older sessions.
403		if (hasExistingSession) {
404			if (!hasThinkingEntry) {
405				sessionManager.appendThinkingLevelChange(thinkingLevel);
406			}
407		} else {
408			// Save initial model and thinking level for new sessions so they can be restored on resume
409			if (model) {
410				sessionManager.appendModelChange(model.provider, model.id);
411			}
412			sessionManager.appendThinkingLevelChange(thinkingLevel);
413		}
414	
415		const session = new AgentSession({
416			agent,
417			sessionManager,
418			settingsManager,
419			cwd,
420			scopedModels: options.scopedModels,
421			resourceLoader,
422			customTools: options.customTools,
423			modelRuntime,
424			cacheWarmer,
425			initialActiveToolNames,
426			allowedToolNames,
427			excludedToolNames,
428			extensionRunnerRef,
429			sessionStartEvent: options.sessionStartEvent,
430		});
431	
432		const extensionsResult = resourceLoader.getExtensions();
433	
434		return {
435			session,
436			extensionsResult,
437			modelFallbackMessage,
438		};
439	}
