1	/**
2	 * Context compaction for long sessions.
3	 *
4	 * Pure functions for compaction logic. The session manager handles I/O,
5	 * and after compaction the session is reloaded.
6	 */
7	
8	import type { AgentMessage, StreamFn, ThinkingLevel } from "@earendil-works/pi-agent-core";
9	import {
10		contentText,
11		getCurrentSystemMessage,
12		normalizeContext,
13		type RetryCallbacks,
14		type RetryPolicy,
15		retryAssistantCall,
16		uuidv7,
17	} from "@earendil-works/pi-ai";
18	import type {
19		AssistantMessage,
20		Model,
21		SimpleStreamOptions,
22		SystemMessage,
23		TranscriptContext,
24		Usage,
25	} from "@earendil-works/pi-ai/compat";
26	import { completeSimple } from "@earendil-works/pi-ai/compat";
27	import { convertToLlm } from "../messages.ts";
28	import {
29		buildSessionProjection,
30		type CompactionEntry,
31		type ProjectedSessionEntry,
32		type SessionEntry,
33		type SessionProjection,
34		sessionEntryToContextMessages,
35	} from "../session-manager.ts";
36	import {
37		computeFileLists,
38		createFileOps,
39		extractFileOpsFromMessage,
40		type FileOperations,
41		formatFileOperations,
42		SUMMARIZATION_SYSTEM_PROMPT,
43		serializeConversation,
44	} from "./utils.ts";
45	
46	// ============================================================================
47	// File Operation Tracking
48	// ============================================================================
49	
50	/** Details stored in CompactionEntry.details for file tracking */
51	export interface CompactionDetails {
52		readFiles: string[];
53		modifiedFiles: string[];
54	}
55	
56	/**
57	 * Extract file operations from messages and previous compaction entries.
58	 */
59	function extractFileOperations(
60		messages: AgentMessage[],
61		entries: SessionEntry[],
62		prevCompactionIndex: number,
63	): FileOperations {
64		const fileOps = createFileOps();
65	
66		// Collect from previous compaction's details (if pi-generated)
67		if (prevCompactionIndex >= 0) {
68			const prevCompaction = entries[prevCompactionIndex] as CompactionEntry;
69			if (!prevCompaction.fromHook && prevCompaction.details) {
70				// fromHook field kept for session file compatibility
71				const details = prevCompaction.details as CompactionDetails;
72				if (Array.isArray(details.readFiles)) {
73					for (const f of details.readFiles) fileOps.read.add(f);
74				}
75				if (Array.isArray(details.modifiedFiles)) {
76					for (const f of details.modifiedFiles) fileOps.edited.add(f);
77				}
78			}
79		}
80	
81		// Extract from tool calls in messages
82		for (const msg of messages) {
83			extractFileOpsFromMessage(msg, fileOps);
84		}
85	
86		return fileOps;
87	}
88	
89	// ============================================================================
90	// Message Extraction
91	// ============================================================================
92	
93	/**
94	 * Extract AgentMessage from an entry if it produces one.
95	 * Returns undefined for entries that don't contribute to LLM context.
96	 */
97	function getMessagesFromProjectedEntryForCompaction(entry: ProjectedSessionEntry): AgentMessage[] {
98		if (entry.sourceEntry.type === "compaction") return [];
99		// System messages are prompt state, not conversation; the compaction entry carries their replay.
100		return entry.messages.filter((message) => message.role !== "system");
101	}
102	
103	/** Result from compact() - SessionManager adds uuid/parentUuid when saving */
104	export interface CompactionResult<T = unknown> {
105		summary: string;
106		firstKeptEntryId: string;
107		tokensBefore: number;
108		estimatedTokensAfter?: number;
109		/** Usage from the LLM call(s) that generated this summary, if available */
110		usage?: Usage;
111		/** Extension-specific data (e.g., ArtifactIndex, version markers for structured compaction) */
112		details?: T;
113	}
114	
115	function combineUsage(first: Usage, second: Usage): Usage {
116		return {
117			input: first.input + second.input,
118			output: first.output + second.output,
119			cacheRead: first.cacheRead + second.cacheRead,
120			cacheWrite: first.cacheWrite + second.cacheWrite,
121			...(first.cacheWrite1h !== undefined || second.cacheWrite1h !== undefined
122				? { cacheWrite1h: (first.cacheWrite1h ?? 0) + (second.cacheWrite1h ?? 0) }
123				: {}),
124			...(first.reasoning !== undefined || second.reasoning !== undefined
125				? { reasoning: (first.reasoning ?? 0) + (second.reasoning ?? 0) }
126				: {}),
127			totalTokens: first.totalTokens + second.totalTokens,
128			cost: {
129				input: first.cost.input + second.cost.input,
130				output: first.cost.output + second.cost.output,
131				cacheRead: first.cost.cacheRead + second.cost.cacheRead,
132				cacheWrite: first.cost.cacheWrite + second.cost.cacheWrite,
133				total: first.cost.total + second.cost.total,
134			},
135		};
136	}
137	
138	// ============================================================================
139	// Types
140	// ============================================================================
141	
142	export interface CompactionSettings {
143		enabled: boolean;
144		reserveTokens: number;
145		keepRecentTokens: number;
146	}
147	
148	export const DEFAULT_COMPACTION_SETTINGS: CompactionSettings = {
149		enabled: true,
150		reserveTokens: 16384,
151		keepRecentTokens: 20000,
152	};
153	
154	// ============================================================================
155	// Token calculation
156	// ============================================================================
157	
158	/**
159	 * Calculate total context tokens from usage.
160	 * Uses the native totalTokens field when available, falls back to computing from components.
161	 */
162	export function calculateContextTokens(usage: Usage): number {
163		return usage.totalTokens || usage.input + usage.output + usage.cacheRead + usage.cacheWrite;
164	}
165	
166	/**
167	 * Get usage from an assistant message if available.
168	 * Skips aborted, error, and all-zero usage messages as they don't have valid usage data.
169	 */
170	function getAssistantUsage(msg: AgentMessage): Usage | undefined {
171		if (msg.role === "assistant" && "usage" in msg) {
172			const assistantMsg = msg as AssistantMessage;
173			if (
174				assistantMsg.stopReason !== "aborted" &&
175				assistantMsg.stopReason !== "error" &&
176				assistantMsg.usage &&
177				calculateContextTokens(assistantMsg.usage) > 0
178			) {
179				return assistantMsg.usage;
180			}
181		}
182		return undefined;
183	}
184	
185	/**
186	 * Find the last valid assistant message usage from session entries.
187	 */
188	export function getLastAssistantUsage(entries: SessionEntry[]): Usage | undefined {
189		for (let i = entries.length - 1; i >= 0; i--) {
190			const entry = entries[i];
191			if (entry.type === "message") {
192				const usage = getAssistantUsage(entry.message);
193				if (usage) return usage;
194			}
195		}
196		return undefined;
197	}
198	
199	export interface ContextUsageEstimate {
200		tokens: number;
201		usageTokens: number;
202		trailingTokens: number;
203		lastUsageIndex: number | null;
204	}
205	
206	function getLastAssistantUsageInfo(messages: AgentMessage[]): { usage: Usage; index: number } | undefined {
207		for (let i = messages.length - 1; i >= 0; i--) {
208			const usage = getAssistantUsage(messages[i]);
209			if (usage) return { usage, index: i };
210		}
211		return undefined;
212	}
213	
214	/**
215	 * Estimate context tokens from messages, using the last assistant usage when available.
216	 * If there are messages after the last usage, estimate their tokens with estimateTokens.
217	 */
218	export function estimateContextTokens(messages: AgentMessage[]): ContextUsageEstimate {
219		const usageInfo = getLastAssistantUsageInfo(messages);
220	
221		if (!usageInfo) {
222			let estimated = 0;
223			for (const message of messages) {
224				estimated += estimateTokens(message);
225			}
226			return {
227				tokens: estimated,
228				usageTokens: 0,
229				trailingTokens: estimated,
230				lastUsageIndex: null,
231			};
232		}
233	
234		const usageTokens = calculateContextTokens(usageInfo.usage);
235		let trailingTokens = 0;
236		for (let i = usageInfo.index + 1; i < messages.length; i++) {
237			trailingTokens += estimateTokens(messages[i]);
238		}
239	
240		return {
241			tokens: usageTokens + trailingTokens,
242			usageTokens,
243			trailingTokens,
244			lastUsageIndex: usageInfo.index,
245		};
246	}
247	
248	/** Estimate projected context without trusting usage captured before a later edit or compaction. */
249	export function estimateProjectedContextTokens(
250		projection: SessionProjection,
251		branchEntries: SessionEntry[],
252	): ContextUsageEstimate {
253		const estimate = estimateContextTokens(projection.messages);
254		if (estimate.lastUsageIndex !== null) {
255			let projectedMessageIndex = 0;
256			let usageEntryId: string | undefined;
257			for (const entry of projection.entries) {
258				const nextMessageIndex = projectedMessageIndex + entry.messages.length;
259				if (estimate.lastUsageIndex < nextMessageIndex) {
260					usageEntryId = entry.sourceEntry.id;
261					break;
262				}
263				projectedMessageIndex = nextMessageIndex;
264			}
265	
266			const usageEntryIndex = usageEntryId ? branchEntries.findIndex((entry) => entry.id === usageEntryId) : -1;
267			let latestInvalidatingEntryIndex = -1;
268			for (let i = branchEntries.length - 1; i >= 0; i--) {
269				const entry = branchEntries[i];
270				if (entry.type === "context_edit" || entry.type === "compaction") {
271					latestInvalidatingEntryIndex = i;
272					break;
273				}
274			}
275			if (usageEntryIndex > latestInvalidatingEntryIndex) return estimate;
276		}
277	
278		const currentSystem = getCurrentSystemMessage(projection.messages);
279		let tokens = currentSystem ? estimateTokens(currentSystem) : 0;
280		for (const message of projection.messages) {
281			if (message.role !== "system") tokens += estimateTokens(message);
282		}
283		return { tokens, usageTokens: 0, trailingTokens: tokens, lastUsageIndex: null };
284	}
285	
286	/**
287	 * Check if compaction should trigger based on context usage.
288	 */
289	export function shouldCompact(contextTokens: number, contextWindow: number, settings: CompactionSettings): boolean {
290		if (!settings.enabled) return false;
291		return contextTokens > contextWindow - settings.reserveTokens;
292	}
293	
294	// ============================================================================
295	// Cut point detection
296	// ============================================================================
297	
298	const ESTIMATED_IMAGE_CHARS = 4800;
299	
300	function estimateTextAndImageContentChars(content: string | Array<{ type: string; text?: string }>): number {
301		if (typeof content === "string") {
302			return content.length;
303		}
304	
305		let chars = 0;
306		for (const block of content) {
307			if (block.type === "text" && block.text) {
308				chars += block.text.length;
309			} else if (block.type === "image") {
310				chars += ESTIMATED_IMAGE_CHARS;
311			}
312		}
313		return chars;
314	}
315	
316	/**
317	 * Estimate token count for a message using chars/4 heuristic.
318	 * This is conservative (overestimates tokens).
319	 */
320	export function estimateTokens(message: AgentMessage): number {
321		let chars = 0;
322	
323		switch (message.role) {
324			case "system": {
325				const system = message as SystemMessage;
326				chars = estimateTextAndImageContentChars(system.content);
327				if (system.sections) {
328					for (const section of Object.values(system.sections)) {
329						if (section) chars += section.length;
330					}
331				}
332				if (system.toolsAdded) chars += JSON.stringify(system.toolsAdded).length;
333				return Math.ceil(chars / 4);
334			}
335			case "user": {
336				chars = estimateTextAndImageContentChars(
337					(message as { content: string | Array<{ type: string; text?: string }> }).content,
338				);
339				return Math.ceil(chars / 4);
340			}
341			case "assistant": {
342				const assistant = message as AssistantMessage;
343				for (const block of assistant.content) {
344					if (block.type === "text") {
345						chars += block.text.length;
346					} else if (block.type === "thinking") {
347						chars += block.thinking.length;
348					} else if (block.type === "toolCall") {
349						chars += block.name.length + JSON.stringify(block.arguments).length;
350					}
351				}
352				return Math.ceil(chars / 4);
353			}
354			case "custom":
355			case "toolResult": {
356				chars = estimateTextAndImageContentChars(message.content);
357				return Math.ceil(chars / 4);
358			}
359			case "bashExecution": {
360				chars = message.command.length + message.output.length;
361				return Math.ceil(chars / 4);
362			}
363			case "branchSummary":
364			case "compactionSummary": {
365				chars = message.summary.length;
366				return Math.ceil(chars / 4);
367			}
368		}
369	
370		return 0;
371	}
372	
373	function isCutPointMessage(message: AgentMessage): boolean {
374		switch (message.role) {
375			case "user":
376			case "assistant":
377			case "bashExecution":
378			case "custom":
379			case "branchSummary":
380			case "compactionSummary":
381				return true;
382			case "toolResult":
383				return false;
384		}
385		return false;
386	}
387	
388	function isTurnStartMessage(message: AgentMessage): boolean {
389		switch (message.role) {
390			case "user":
391			case "bashExecution":
392			case "custom":
393			case "branchSummary":
394			case "compactionSummary":
395				return true;
396			case "assistant":
397			case "toolResult":
398				return false;
399		}
400		return false;
401	}
402	
403	function isTurnStartEntry(entry: SessionEntry): boolean {
404		if (entry.type === "compaction") {
405			return false;
406		}
407		return sessionEntryToContextMessages(entry).some(isTurnStartMessage);
408	}
409	
410	/**
411	 * Find valid cut points: indices of context-visible user-like or assistant messages.
412	 * Never cut at tool results (they must follow their tool call).
413	 * When we cut at an assistant message with tool calls, its tool results follow it
414	 * and will be kept.
415	 */
416	function findValidCutPoints(entries: SessionEntry[], startIndex: number, endIndex: number): number[] {
417		const cutPoints: number[] = [];
418		for (let i = startIndex; i < endIndex; i++) {
419			const entry = entries[i];
420			if (entry.type === "compaction") {
421				continue;
422			}
423			if (sessionEntryToContextMessages(entry).some(isCutPointMessage)) {
424				cutPoints.push(i);
425			}
426		}
427		return cutPoints;
428	}
429	
430	/**
431	 * Find the context-visible user-role message that starts the turn containing the given entry index.
432	 * Returns -1 if no turn start found before the index.
433	 */
434	export function findTurnStartIndex(entries: SessionEntry[], entryIndex: number, startIndex: number): number {
435		for (let i = entryIndex; i >= startIndex; i--) {
436			if (isTurnStartEntry(entries[i])) {
437				return i;
438			}
439		}
440		return -1;
441	}
442	
443	export interface CutPointResult {
444		/** Index of first entry to keep */
445		firstKeptEntryIndex: number;
446		/** Index of user message that starts the turn being split, or -1 if not splitting */
447		turnStartIndex: number;
448		/** Whether this cut splits a turn (cut point is not a user message) */
449		isSplitTurn: boolean;
450	}
451	
452	/**
453	 * Find the cut point in session entries that keeps approximately `keepRecentTokens`.
454	 *
455	 * Algorithm: Walk backwards from newest, accumulating estimated message sizes.
456	 * Stop when we've accumulated >= keepRecentTokens. Cut at that point.
457	 *
458	 * Can cut at user OR assistant messages (never tool results). When cutting at an
459	 * assistant message with tool calls, its tool results come after and will be kept.
460	 *
461	 * Returns CutPointResult with:
462	 * - firstKeptEntryIndex: the entry index to start keeping from
463	 * - turnStartIndex: if cutting mid-turn, the user message that started that turn
464	 * - isSplitTurn: whether we're cutting in the middle of a turn
465	 *
466	 * Only considers entries between `startIndex` and `endIndex` (exclusive).
467	 */
468	export function findCutPoint(
469		entries: SessionEntry[],
470		startIndex: number,
471		endIndex: number,
472		keepRecentTokens: number,
473	): CutPointResult {
474		const cutPoints = findValidCutPoints(entries, startIndex, endIndex);
475	
476		if (cutPoints.length === 0) {
477			return { firstKeptEntryIndex: startIndex, turnStartIndex: -1, isSplitTurn: false };
478		}
479	
480		// Walk backwards from newest, accumulating estimated message sizes
481		let accumulatedTokens = 0;
482		let cutIndex = cutPoints[0]; // Default: keep from first message (not header)
483	
484		for (let i = endIndex - 1; i >= startIndex; i--) {
485			const entry = entries[i];
486			const messageTokens = sessionEntryToContextMessages(entry).reduce(
487				(sum, message) => sum + estimateTokens(message),
488				0,
489			);
490			if (messageTokens === 0) continue;
491			accumulatedTokens += messageTokens;
492	
493			// Check if we've exceeded the budget
494			if (accumulatedTokens >= keepRecentTokens) {
495				// Prefer the closest valid cut point at or after this entry. If trailing
496				// tool results exceed the budget by themselves, keep their preceding
497				// assistant tool call instead of falling back to the first message.
498				cutIndex = cutPoints.find((candidate) => candidate >= i) ?? cutPoints[cutPoints.length - 1];
499				break;
500			}
501		}
502	
503		// Scan backwards from cutIndex to include adjacent metadata entries that do not affect context.
504		while (cutIndex > startIndex) {
505			const prevEntry = entries[cutIndex - 1];
506			// Stop at compaction boundaries or context-visible entries.
507			if (prevEntry.type === "compaction" || sessionEntryToContextMessages(prevEntry).length > 0) {
508				break;
509			}
510			cutIndex--;
511		}
512	
513		// Determine if this is a split turn
514		const cutEntry = entries[cutIndex];
515		const startsTurn = isTurnStartEntry(cutEntry);
516		const turnStartIndex = startsTurn ? -1 : findTurnStartIndex(entries, cutIndex, startIndex);
517	
518		return {
519			firstKeptEntryIndex: cutIndex,
520			turnStartIndex,
521			isSplitTurn: !startsTurn && turnStartIndex !== -1,
522		};
523	}
