603	/**
604	 * Returns an error message when a summarization response cannot safely be persisted.
605	 * A length stop contains partial text and must not become a session checkpoint.
606	 */
607	export function getSummarizationFailure(response: AssistantMessage, label: string): string | undefined {
608		if (response.stopReason === "error") {
609			return `${label} failed: ${response.errorMessage || "Unknown error"}`;
610		}
611		if (response.stopReason === "length") {
612			return `${label} failed: generation hit the token cap and the summary is incomplete`;
613		}
614		return undefined;
615	}
