617	function createSummarizationOptions(
618		model: Model<any>,
619		maxTokens: number,
620		apiKey: string | undefined,
621		headers: Record<string, string> | undefined,
622		env: Record<string, string> | undefined,
623		signal: AbortSignal | undefined,
624		thinkingLevel: ThinkingLevel | undefined,
625		sessionId: string | undefined,
626	): SimpleStreamOptions {
627		const options: SimpleStreamOptions = { maxTokens, signal, apiKey, headers, env, sessionId };
628		if (model.reasoning && thinkingLevel && thinkingLevel !== "off") {
629			options.reasoning = thinkingLevel;
630		}
631		return options;
