634	/**
635	 * Shared choke point for every compaction/branch-summary summarization call. Wraps the
636	 * single LLM call in {@link retryAssistantCall} so transient stream drops (e.g.
637	 * `terminated`, socket close) honor the configured retry policy instead of failing
638	 * the whole compaction on the first attempt. Deterministic errors and aborts return
639	 * immediately (see {@link retryAssistantCall}).
640	 */
641	export async function completeSummarization(
642		model: Model<any>,
643		context: TranscriptContext,
644		options: SimpleStreamOptions,
645		streamFn?: StreamFn,
646		retry?: RetryPolicy,
647		callbacks?: RetryCallbacks,
648	): Promise<AssistantMessage> {
649		// Avoid cache writes for one-off summaries. Reuse caller-supplied routing when available;
650		// callers without a session ID, including branch summaries, receive a fresh routing ID.
651		const requestOptions: SimpleStreamOptions = {
652			...options,
653			cacheRetention: "none",
654			sessionId: options.sessionId ?? uuidv7(),
655		};
656		const produce = async (): Promise<AssistantMessage> =>
657			streamFn
658				? (await streamFn(model, context, requestOptions)).result()
659				: completeSimple(model, context, requestOptions);
660		return retryAssistantCall(produce, retry, requestOptions.signal, callbacks);
661	}
