717	/** Generate or update a conversation summary and return its provider usage. */
718	export async function generateSummaryWithUsage(
719		currentMessages: AgentMessage[],
720		model: Model<any>,
721		reserveTokens: number,
722		apiKey: string | undefined,
723		headers?: Record<string, string>,
724		signal?: AbortSignal,
725		customInstructions?: string,
726		previousSummary?: string,
727		thinkingLevel?: ThinkingLevel,
728		streamFn?: StreamFn,
729		env?: Record<string, string>,
730		retry?: RetryPolicy,
731		callbacks?: RetryCallbacks,
732		sessionId?: string,
733	): Promise<{ text: string; usage: Usage }> {
734		const maxTokens = Math.min(
735			Math.floor(0.8 * reserveTokens),
736			model.maxTokens > 0 ? model.maxTokens : Number.POSITIVE_INFINITY,
737		);
738	
739		// Use update prompt if we have a previous summary, otherwise initial prompt
740		let basePrompt = previousSummary ? UPDATE_SUMMARIZATION_PROMPT : SUMMARIZATION_PROMPT;
741		if (customInstructions) {
742			basePrompt = `${basePrompt}\n\nAdditional focus: ${customInstructions}`;
743		}
744	
745		// Serialize conversation to text so model doesn't try to continue it
746		// Convert to LLM messages first (handles custom types like bashExecution, custom, etc.)
747		const llmMessages = convertToLlm(currentMessages);
748		const conversationText = serializeConversation(llmMessages);
749	
750		// Build the prompt with conversation wrapped in tags
751		let promptText = `<conversation>\n${conversationText}\n</conversation>\n\n`;
752		if (previousSummary) {
753			promptText += `<previous-summary>\n${previousSummary}\n</previous-summary>\n\n`;
754		}
755		promptText += basePrompt;
756	
757		const completionOptions = createSummarizationOptions(
758			model,
759			maxTokens,
760			apiKey,
761			headers,
762			env,
763			signal,
764			thinkingLevel,
765			sessionId,
766		);
767	
768		const response = await completeSummarization(
769			model,
770			buildSummarizationContext(promptText),
771			completionOptions,
772			streamFn,
773			retry,
774			callbacks,
775		);
776	
777		const failure = getSummarizationFailure(response, "Summarization");
778		if (failure) {
779			throw new Error(failure);
780		}
781		if (response.content.some((block) => block.type === "toolCall")) {
782			throw new Error("Summarization attempted to call a tool");
783		}
784	
785		const textContent = contentText(response.content);
786	
787		return { text: textContent, usage: response.usage };
788	}
