794	export interface CompactionPreparation {
795		/** UUID of first entry to keep */
796		firstKeptEntryId: string;
797		/** Messages that will be summarized and discarded */
798		messagesToSummarize: AgentMessage[];
799		/** Messages that will be turned into turn prefix summary (if splitting) */
800		turnPrefixMessages: AgentMessage[];
801		/** Whether this is a split turn (cut point in middle of turn) */
802		isSplitTurn: boolean;
803		tokensBefore: number;
804		/** Summary from previous compaction, for iterative update */
805		previousSummary?: string;
806		/** File operations extracted from messagesToSummarize */
807		fileOps: FileOperations;
808		/** Compaction settions from settings.jsonl	*/
809		settings: CompactionSettings;
810	}
811	
812	function isProjectedTurnStart(entry: ProjectedSessionEntry): boolean {
813		if (entry.sourceEntry.type === "compaction") return false;
814		return entry.messages.some(isTurnStartMessage);
815	}
816	
817	function findProjectedTurnStartIndex(entries: ProjectedSessionEntry[], entryIndex: number, startIndex: number): number {
818		for (let i = entryIndex; i >= startIndex; i--) {
819			if (isProjectedTurnStart(entries[i])) return i;
820		}
821		return -1;
822	}
823	
824	function findProjectedCutPoint(
825		entries: ProjectedSessionEntry[],
826		startIndex: number,
827		endIndex: number,
828		keepRecentTokens: number,
829	): CutPointResult {
830		const cutPoints: number[] = [];
831		for (let i = startIndex; i < endIndex; i++) {
832			const entry = entries[i];
833			if (entry.sourceEntry.type !== "compaction" && entry.messages.some(isCutPointMessage)) cutPoints.push(i);
834		}
835		if (cutPoints.length === 0) {
836			return { firstKeptEntryIndex: startIndex, turnStartIndex: -1, isSplitTurn: false };
837		}
838	
839		let accumulatedTokens = 0;
840		let exceededBudget = false;
841		let cutIndex = cutPoints[0];
842		for (let i = endIndex - 1; i >= startIndex; i--) {
843			const messageTokens = entries[i].messages.reduce((sum, message) => sum + estimateTokens(message), 0);
844			if (messageTokens === 0) continue;
845			accumulatedTokens += messageTokens;
846			if (accumulatedTokens >= keepRecentTokens) {
847				exceededBudget = true;
848				cutIndex = cutPoints.find((candidate) => candidate >= i) ?? cutPoints[cutPoints.length - 1];
849				break;
850			}
851		}
852	
853		// A recovery attempt and its omission edits are context-invisible after the last
854		// visible input. Advance only for a closed suffix containing an omitted assistant
855		// attempt; arbitrary metadata must not move the cut past unsent input.
856		const suffix = entries.slice(cutIndex + 1, endIndex);
857		const isIntrinsicallyVisible = (entry: ProjectedSessionEntry): boolean =>
858			entry.sourceEntry.type !== "context_edit" && sessionEntryToContextMessages(entry.sourceEntry).length > 0;
859		const isOmitted = (entry: ProjectedSessionEntry): boolean =>
860			isIntrinsicallyVisible(entry) && entry.messages.length === 0;
861		const omittedSuffixIds = new Set(suffix.filter(isOmitted).map((entry) => entry.sourceEntry.id));
862		const hasExternalReplacement = suffix.some(
863			(entry) =>
864				entry.sourceEntry.type === "context_edit" &&
865				entry.sourceEntry.replacement !== null &&
866				!omittedSuffixIds.has(entry.sourceEntry.targetId),
867		);
868		const isRecoveryOmissionSuffix =
869			exceededBudget &&
870			!hasExternalReplacement &&
871			suffix.some(
872				(entry) =>
873					entry.sourceEntry.type === "message" && entry.sourceEntry.message.role === "assistant" && isOmitted(entry),
874			) &&
875			suffix.every(
876				(entry) => entry.sourceEntry.type !== "compaction" && (!isIntrinsicallyVisible(entry) || isOmitted(entry)),
877			);
878		if (isRecoveryOmissionSuffix) cutIndex++;
879	
880		while (cutIndex > startIndex) {
881			const previous = entries[cutIndex - 1];
882			if (previous.sourceEntry.type === "compaction" || previous.messages.length > 0) break;
883			cutIndex--;
884		}
885		const startsTurn = isProjectedTurnStart(entries[cutIndex]);
886		const turnStartIndex = startsTurn ? -1 : findProjectedTurnStartIndex(entries, cutIndex, startIndex);
887		return {
888			firstKeptEntryIndex: cutIndex,
889			turnStartIndex,
890			isSplitTurn: !startsTurn && turnStartIndex !== -1,
891		};
892	}
893	
894	export function prepareCompaction(
895		pathEntries: SessionEntry[],
896		settings: CompactionSettings,
897	): CompactionPreparation | undefined {
898		if (pathEntries.length > 0 && pathEntries[pathEntries.length - 1].type === "compaction") {
899			return undefined;
900		}
901	
902		const projection = buildSessionProjection(pathEntries);
903		const projectedEntries = projection.entries;
904		const sourceEntries = projectedEntries.map((entry) => entry.sourceEntry);
905		// The newest compaction is projected first. Older compaction entries can still
906		// occur in its retained raw range, but their projected contribution is empty.
907		const prevCompactionIndex = projectedEntries.findIndex(
908			(entry) => entry.sourceEntry.type === "compaction" && entry.messages.length > 0,
909		);
910	
911		let previousSummary: string | undefined;
912		let boundaryStart = 0;
913		if (prevCompactionIndex >= 0) {
914			previousSummary = (projectedEntries[prevCompactionIndex].sourceEntry as CompactionEntry).summary;
915			// The canonical projection has already selected the previous compaction's retained tail.
916			boundaryStart = prevCompactionIndex + 1;
917		}
918		const boundaryEnd = projectedEntries.length;
919		const tokensBefore = estimateProjectedContextTokens(projection, pathEntries).tokens;
920		const cutPoint = findProjectedCutPoint(projectedEntries, boundaryStart, boundaryEnd, settings.keepRecentTokens);
921	
922		const firstKeptEntry = projectedEntries[cutPoint.firstKeptEntryIndex]?.sourceEntry;
923		if (!firstKeptEntry?.id) return undefined;
924		const firstKeptEntryId = firstKeptEntry.id;
925		const historyEnd = cutPoint.isSplitTurn ? cutPoint.turnStartIndex : cutPoint.firstKeptEntryIndex;
926	
927		const messagesToSummarize = projectedEntries
928			.slice(boundaryStart, historyEnd)
929			.flatMap(getMessagesFromProjectedEntryForCompaction);
930		const turnPrefixMessages = cutPoint.isSplitTurn
931			? projectedEntries
932					.slice(cutPoint.turnStartIndex, cutPoint.firstKeptEntryIndex)
933					.flatMap(getMessagesFromProjectedEntryForCompaction)
934			: [];
935	
936		if (messagesToSummarize.length === 0 && turnPrefixMessages.length === 0) return undefined;
937	
938		// Extract file operations from edited model-visible messages and the previous compaction.
939		const fileOps = extractFileOperations(messagesToSummarize, sourceEntries, prevCompactionIndex);
940	
941		// Also extract file ops from turn prefix if splitting
942		if (cutPoint.isSplitTurn) {
943			for (const msg of turnPrefixMessages) {
944				extractFileOpsFromMessage(msg, fileOps);
945			}
946		}
947	
948		return {
949			firstKeptEntryId,
950			messagesToSummarize,
951			turnPrefixMessages,
952			isSplitTurn: cutPoint.isSplitTurn,
953			tokensBefore,
954			previousSummary,
955			fileOps,
956			settings,
957		};
958	}
