979	/**
980	 * Generate summaries for compaction using prepared data.
981	 * Returns CompactionResult - SessionManager adds uuid/parentUuid when saving.
982	 *
983	 * @param preparation - Pre-calculated preparation from prepareCompaction()
984	 * @param customInstructions - Optional custom focus for the summary
985	 * @param sessionId - Optional routing session ID forwarded without enabling prompt caching
986	 */
987	export async function compact(
988		preparation: CompactionPreparation,
989		model: Model<any>,
990		apiKey: string | undefined,
991		headers?: Record<string, string>,
992		customInstructions?: string,
993		signal?: AbortSignal,
994		thinkingLevel?: ThinkingLevel,
995		streamFn?: StreamFn,
996		env?: Record<string, string>,
997		retry?: RetryPolicy,
998		callbacks?: RetryCallbacks,
999		sessionId?: string,
1000	): Promise<CompactionResult> {
1001		const {
1002			firstKeptEntryId,
1003			messagesToSummarize,
1004			turnPrefixMessages,
1005			isSplitTurn,
1006			tokensBefore,
1007			previousSummary,
1008			fileOps,
1009			settings,
1010		} = preparation;
1011	
1012		// Generate summaries and merge into one
1013		let summary: string;
1014		let summaryUsage: Usage;
1015	
1016		if (isSplitTurn && turnPrefixMessages.length > 0) {
1017			let historyText = previousSummary ?? "No prior history.";
1018			let historyUsage: Usage | undefined;
1019			if (messagesToSummarize.length > 0) {
1020				const historyResult = await generateSummaryWithUsage(
1021					messagesToSummarize,
1022					model,
1023					settings.reserveTokens,
1024					apiKey,
1025					headers,
1026					signal,
1027					customInstructions,
1028					previousSummary,
1029					thinkingLevel,
1030					streamFn,
1031					env,
1032					retry,
1033					callbacks,
1034					sessionId,
1035				);
1036				historyText = historyResult.text;
1037				historyUsage = historyResult.usage;
1038			}
1039			const turnPrefixResult = await generateTurnPrefixSummary(
1040				turnPrefixMessages,
1041				model,
1042				settings.reserveTokens,
1043				apiKey,
1044				headers,
1045				env,
1046				signal,
1047				thinkingLevel,
1048				streamFn,
1049				retry,
1050				callbacks,
1051				sessionId,
1052			);
1053			// Merge into single summary
1054			summary = `${historyText}\n\n---\n\n**Turn Context (split turn):**\n\n${turnPrefixResult.text}`;
1055			summaryUsage = historyUsage ? combineUsage(historyUsage, turnPrefixResult.usage) : turnPrefixResult.usage;
1056		} else {
1057			// Just generate history summary
1058			const result = await generateSummaryWithUsage(
1059				messagesToSummarize,
1060				model,
1061				settings.reserveTokens,
1062				apiKey,
1063				headers,
1064				signal,
1065				customInstructions,
1066				previousSummary,
1067				thinkingLevel,
1068				streamFn,
1069				env,
1070				retry,
1071				callbacks,
1072				sessionId,
1073			);
1074			summary = result.text;
1075			summaryUsage = result.usage;
1076		}
1077	
1078		// Compute file lists and append to summary
1079		const { readFiles, modifiedFiles } = computeFileLists(fileOps);
1080		summary += formatFileOperations(readFiles, modifiedFiles);
1081	
1082		if (!firstKeptEntryId) {
1083			throw new Error("First kept entry has no UUID - session may need migration");
1084		}
1085	
1086		return {
1087			summary,
1088			firstKeptEntryId,
1089			tokensBefore,
1090			usage: summaryUsage,
1091			details: { readFiles, modifiedFiles } as CompactionDetails,
1092		};
1093	}
