1095	/**
1096	 * Generate a summary for a turn prefix (when splitting a turn).
1097	 */
1098	async function generateTurnPrefixSummary(
1099		messages: AgentMessage[],
1100		model: Model<any>,
1101		reserveTokens: number,
1102		apiKey: string | undefined,
1103		headers?: Record<string, string>,
1104		env?: Record<string, string>,
1105		signal?: AbortSignal,
1106		thinkingLevel?: ThinkingLevel,
1107		streamFn?: StreamFn,
1108		retry?: RetryPolicy,
1109		callbacks?: RetryCallbacks,
1110		sessionId?: string,
1111	): Promise<{ text: string; usage: Usage }> {
1112		const maxTokens = Math.min(
1113			Math.floor(0.5 * reserveTokens),
1114			model.maxTokens > 0 ? model.maxTokens : Number.POSITIVE_INFINITY,
1115		); // Smaller budget for turn prefix
1116		const llmMessages = convertToLlm(messages);
1117		const conversationText = serializeConversation(llmMessages);
1118		const promptText = `# Conversation\n${conversationText}\n\n# Instructions\n${TURN_PREFIX_SUMMARIZATION_PROMPT}`;
1119	
1120		const response = await completeSummarization(
1121			model,
1122			buildSummarizationContext(promptText),
1123			createSummarizationOptions(model, maxTokens, apiKey, headers, env, signal, thinkingLevel, sessionId),
1124			streamFn,
1125			retry,
1126			callbacks,
1127		);
1128	
1129		const failure = getSummarizationFailure(response, "Turn prefix summarization");
1130		if (failure) {
1131			throw new Error(failure);
