2700			// For error messages or all-zero usage messages, estimate from the last valid response.
2701			// This ensures sessions that hit persistent API errors (e.g. 529) or malformed zero-usage
2702			// responses can still compact and do not reset context accounting.
2703			let contextTokens: number;
2704			const projection = currentProjection;
2705			const hasContextEdits = projection.entries.some((entry) => entry.sourceEntry.type === "context_edit");
2706			const directContextTokens = assistantMessage.usage ? calculateContextTokens(assistantMessage.usage) : 0;
2707			if (hasContextEdits) {
2708				contextTokens = estimateProjectedContextTokens(projection, branch).tokens;
2709			} else if (assistantMessage.stopReason === "error" || directContextTokens === 0) {
2710				const messages = this.agent.state.messages;
2711				const estimate = estimateContextTokens(messages);
2712				// Without provider usage, estimate.tokens is the pure message-size estimate.
2713				// Only usage-backed estimates need the stale pre-compaction check.
2714				if (estimate.lastUsageIndex !== null) {
2715					// Verify the usage source is post-compaction. Kept pre-compaction messages
2716					// have stale usage reflecting the old (larger) context and would falsely
2717					// trigger compaction right after one just finished.
2718					const usageMsg = messages[estimate.lastUsageIndex];
2719					if (
2720						compactionEntry &&
2721						usageMsg.role === "assistant" &&
2722						(usageMsg as AssistantMessage).timestamp <= new Date(compactionEntry.timestamp).getTime()
2723					) {
2724						return false;
2725					}
2726				}
2727				contextTokens = estimate.tokens;
2728			} else {
2729				contextTokens = directContextTokens;
2730			}
2731			if (shouldCompact(contextTokens, contextWindow, settings)) {
2732				return await this._runAutoCompaction("threshold", false);
2733			}
2734			return false;
2735		}
2736	
2737		/**
2738		 * Execute threshold or overflow compaction. Manual compaction uses
2739		 * `AgentSession.compact()` instead. Both paths call the lower-level `compact()`
2740		 * function imported from `./compaction/index.ts` after preparation and extension
2741		 * interception.
2742		 *
2743		 * @param reason Automatic trigger selected by `_checkCompaction()`
2744		 * @param willRetry Whether to continue the interrupted turn after overflow compaction
2745		 * @returns Whether the post-run loop should call `agent.continue()`
2746		 */
2747		private async _runAutoCompaction(reason: "overflow" | "threshold", willRetry: boolean): Promise<boolean> {
2748			const model = this.model;
2749			const settings = this.settingsManager.getCompactionSettings(model);
2750			let abortController: AbortController | undefined;
2751			let started = false;
2752			let fromExtension = false;
2753			let cancelledByExtension = false;
2754	
2755			try {
2756				if (!model) {
2757					return false;
2758				}
2759	
2760				const pathEntries = this.sessionManager.getBranch();
2761				const preparation = prepareCompaction(pathEntries, settings);
2762				if (!preparation) {
2763					return false;
2764				}
2765	
2766				abortController = new AbortController();
2767				this._autoCompactionAbortController = abortController;
2768				started = true;
2769				this._emit({ type: "compaction_start", reason });
2770				abortController.signal.throwIfAborted();
2771	
2772				const {
2773					model: requestModel,
2774					apiKey,
2775					headers,
2776					env,
2777				} = await this._getSummarizationRequestAuth(model, abortController.signal);
2778				abortController.signal.throwIfAborted();
2779	
2780				let extensionCompaction: CompactionResult | undefined;
2781	
2782				if (this._extensionRunner.hasHandlers("session_before_compact")) {
2783					const extensionResult = (await this._extensionRunner.emit({
2784						type: "session_before_compact",
2785						preparation,
2786						branchEntries: pathEntries,
2787						customInstructions: undefined,
2788						reason,
2789						willRetry,
2790						signal: abortController.signal,
2791					})) as SessionBeforeCompactResult | undefined;
2792	
2793					if (extensionResult?.cancel) {
2794						cancelledByExtension = true;
2795						throw new Error("Compaction cancelled");
2796					}
2797	
2798					if (extensionResult?.compaction) {
2799						extensionCompaction = extensionResult.compaction;
2800						fromExtension = true;
2801					}
2802				}
2803				abortController.signal.throwIfAborted();
2804	
2805				let summary: string;
2806				let firstKeptEntryId: string;
2807				let tokensBefore: number;
2808				let usage: Usage | undefined;
2809				let details: unknown;
2810	
2811				if (extensionCompaction) {
2812					// Extension provided compaction content
2813					summary = extensionCompaction.summary;
2814					firstKeptEntryId = extensionCompaction.firstKeptEntryId;
2815					tokensBefore = extensionCompaction.tokensBefore;
2816					usage = extensionCompaction.usage;
2817					details = extensionCompaction.details;
2818				} else {
2819					// Shared default summary generator, also used by manual compaction.
2820					const compactResult = await this._runDefaultCompaction(
2821						preparation,
2822						requestModel,
2823						apiKey,
2824						headers,
2825						undefined,
2826						abortController.signal,
2827						env,
2828						reason,
2829					);
2830					summary = compactResult.summary;
2831					firstKeptEntryId = compactResult.firstKeptEntryId;
2832					tokensBefore = compactResult.tokensBefore;
2833					usage = compactResult.usage;
2834					details = compactResult.details;
2835				}
2836				abortController.signal.throwIfAborted();
2837	
2838				this.sessionManager.appendCompaction(summary, firstKeptEntryId, tokensBefore, details, fromExtension, usage);
2839				const newEntries = this.sessionManager.getEntries();
2840				this._refreshFinalizedContext();
2841				const estimatedTokensAfter = estimateMessagesTokens(this.sessionManager.buildSessionProjection().messages);
2842	
2843				// Get the saved compaction entry for the extension event
2844				const savedCompactionEntry = newEntries.find((e) => e.type === "compaction" && e.summary === summary) as
2845					| CompactionEntry
2846					| undefined;
2847	
2848				if (this._extensionRunner && savedCompactionEntry) {
2849					await this._extensionRunner.emit({
2850						type: "session_compact",
2851						compactionEntry: savedCompactionEntry,
2852						fromExtension,
2853						reason,
2854						willRetry,
2855					});
2856				}
2857	
2858				const result: CompactionResult = {
2859					summary,
2860					firstKeptEntryId,
2861					tokensBefore,
2862					estimatedTokensAfter,
2863					usage,
2864					details,
2865				};
2866				this._emit({ type: "compaction_end", reason, result, aborted: false, willRetry });
2867	
2868				if (willRetry) return true;
2869	
2870				// Auto-compaction can complete while follow-up/steering/custom messages are waiting.
2871				// Continue once so queued messages are delivered.
2872				return this.agent.hasQueuedMessages();
2873			} catch (error) {
2874				const message = error instanceof Error ? error.message : "compaction failed";
2875				const aborted = abortController?.signal.aborted === true || cancelledByExtension;
2876				if (started) {
2877					const errorMessage = aborted
2878						? undefined
2879						: reason === "overflow"
2880							? `Context overflow recovery failed: ${message}`
2881							: `Auto-compaction failed: ${message}`;
2882					this._emit({
2883						type: "compaction_end",
2884						reason,
2885						result: undefined,
2886						aborted,
2887						willRetry: false,
2888						errorMessage,
2889					});

