1	import type { Context, Message, SystemMessage, Tool, ToolReference, TranscriptContext } from "../types.ts";
2	import { contentText, getSystemMessageText } from "./text.ts";
3	
4	export type { TranscriptContext } from "../types.ts";
5	
6	/**
7	 * Build the leading system message for a prompt and tool set. Returns undefined when
8	 * both are empty, so an empty transcript stays empty.
9	 */
10	export function createInitialSystemMessage(
11		systemPrompt: string | undefined,
12		tools: Tool[] | undefined,
13	): SystemMessage | undefined {
14		const hasSystemPrompt = systemPrompt !== undefined && systemPrompt.length > 0;
15		const hasTools = tools !== undefined && tools.length > 0;
16		if (!hasSystemPrompt && !hasTools) return undefined;
17		return {
18			role: "system",
19			content: systemPrompt ?? "",
20			...(hasTools ? { toolsAdded: tools } : {}),
21			timestamp: 0,
22		};
23	}
24	
25	/**
26	 * Fold `Context.systemPrompt` and `Context.tools` into a leading system message.
27	 * This is the only entry point that produces a {@link TranscriptContext}; every
28	 * provider-facing function expects the result.
29	 */
30	export function normalizeContext(context: Context): TranscriptContext {
31		const initialMessage = createInitialSystemMessage(context.systemPrompt, context.tools);
32		const messages = initialMessage ? [initialMessage, ...context.messages] : context.messages;
33		return { messages } as TranscriptContext;
34	}
35	
36	/**
37	 * Any message list. The replay helpers only read entries whose role is `"system"`, so
38	 * agent transcripts that carry custom message roles can be passed without filtering.
39	 */
40	export type TranscriptMessages = readonly { role: string }[];
41	
42	function isSystemMessage(message: { role: string }): message is SystemMessage {
43		return message.role === "system";
44	}
45	
46	/** Return the leading system message, if the transcript starts with one. */
47	export function getInitialSystemMessage(messages: TranscriptMessages): SystemMessage | undefined {
48		const first = messages[0];
49		return first && isSystemMessage(first) ? first : undefined;
50	}
51	
52	/** Drop the leading system message for APIs that carry the prompt outside the message list. */
53	export function withoutInitialSystemMessage(messages: Message[]): Message[] {
54		return getInitialSystemMessage(messages) ? messages.slice(1) : messages;
55	}
56	
57	/** Resolve the tools available after applying every transcript delta in order. */
58	export function getCurrentTools(messages: TranscriptMessages): Tool[] {
59		const tools = new Map<string, Tool>();
60		for (const message of messages) {
61			if (!isSystemMessage(message)) continue;
62			for (const tool of message.toolsRemoved ?? []) tools.delete(tool.name);
63			for (const tool of message.toolsAdded ?? []) tools.set(tool.name, tool);
64		}
65		return [...tools.values()];
66	}
67	
68	/**
69	 * Replay every system message into one leading system message holding the current
70	 * prompt and tools. Later `content` is appended to the base prompt, `sections` are
71	 * patched by name, and tools are resolved with {@link getCurrentTools}.
72	 */
73	export function getCurrentSystemMessage(messages: TranscriptMessages): SystemMessage | undefined {
74		const content: string[] = [];
75		const sections = new Map<string, string>();
76		let timestamp: number | undefined;
77		for (const message of messages) {
78			if (!isSystemMessage(message)) continue;
79			timestamp ??= message.timestamp;
80			const text = contentText(message.content);
81			if (text.length > 0) content.push(text);
82			for (const [name, value] of Object.entries(message.sections ?? {})) {
83				if (value === null) sections.delete(name);
84				else sections.set(name, value);
85			}
86		}
87		const tools = getCurrentTools(messages);
88		if (timestamp === undefined && tools.length === 0) return undefined;
89		return {
90			role: "system",
91			content: content.join("\n\n"),
92			...(sections.size > 0 ? { sections: Object.fromEntries(sections) } : {}),
93			...(tools.length > 0 ? { toolsAdded: tools } : {}),
94			timestamp: timestamp ?? 0,
95		};
96	}
97	
98	/** Render the current system prompt text after replaying every system message. */
99	export function getCurrentSystemPrompt(messages: TranscriptMessages): string {
100		const message = getCurrentSystemMessage(messages);
101		return message ? getSystemMessageText(message) : "";
102	}
103	
104	/**
105	 * Rebuild the transcript for APIs without mid-conversation system messages: the replayed
106	 * system message leads, and every later system message is dropped.
107	 */
108	export function collapseSystemMessages(context: TranscriptContext): TranscriptContext {
109		const head = getCurrentSystemMessage(context.messages);
110		const messages = context.messages.filter((message) => message.role !== "system");
111		return { messages: head ? [head, ...messages] : messages } as TranscriptContext;
112	}
113	
114	/** Keep later system messages in place when the model accepts them; otherwise collapse them. */
115	export function resolveTranscript(
116		context: TranscriptContext,
117		supportsMidConvoSystemMessages: boolean | undefined,
118	): TranscriptContext {
119		return supportsMidConvoSystemMessages ? context : collapseSystemMessages(context);
120	}
121	
122	/** Strip executable and display-only fields from a tool before transcript comparison or persistence. */
123	export function toToolDeclaration(tool: Tool): Tool {
124		return {
125			name: tool.name,
126			description: tool.description,
127			parameters: JSON.parse(JSON.stringify(tool.parameters)) as Tool["parameters"],
128			...(tool.constrainedSampling === undefined ? {} : { constrainedSampling: tool.constrainedSampling }),
129		};
130	}
131	
132	/**
133	 * Whether two tools declare the same interface to the model.
134	 *
135	 * Both sides go through {@link toToolDeclaration} first: its JSON round-trip drops the
136	 * typebox symbol keys and `undefined` fields that a structural comparison would see, and
137	 * builds both objects with the same key order, so comparing the serialized declarations
138	 * is exact. This avoids a deep-equal dependency in a browser-safe package.
139	 */
140	export function declarationsEqual(left: Tool, right: Tool): boolean {
141		return JSON.stringify(toToolDeclaration(left)) === JSON.stringify(toToolDeclaration(right));
142	}
143	
144	export interface ToolStateChanges {
145		toolsAdded: Tool[];
146		toolsRemoved: ToolReference[];
147	}
148	
149	/** Compare two complete tool states. A changed definition is a removal followed by an addition. */
