198	function messageToText(message: Message): string {
199		if (message.role === "system") {
200			return [
201				getSystemMessageText(message),
202				...(message.toolsRemoved?.map((tool) => `tool-:${JSON.stringify(tool)}`) ?? []),
203				...(message.toolsAdded?.map((tool) => `tool+:${JSON.stringify(tool)}`) ?? []),
204			]
205				.filter((part) => part.length > 0)
206				.join("\n");
207		}
208		if (message.role === "user") {
209			return contentToText(message.content);
210		}
211		if (message.role === "assistant") {
212			return assistantContentToText(message.content);
213		}
214		return toolResultToText(message);
215	}
