217	function serializeContext(context: TranscriptContext): string {
218		return context.messages.map((message) => `${message.role}:${messageToText(message)}`).join("\n\n");
219	}
220	
221	function commonPrefixLength(a: string, b: string): number {
222		const length = Math.min(a.length, b.length);
223		let index = 0;
224		while (index < length && a[index] === b[index]) {
225			index++;
226		}
227		return index;
228	}
229	
230	function withUsageEstimate(
231		message: AssistantMessage,
232		context: TranscriptContext,
233		options: StreamOptions | undefined,
234		promptCache: Map<string, string>,
235	): AssistantMessage {
236		const promptText = serializeContext(context);
237		const promptTokens = estimateTokens(promptText);
238		const outputTokens = estimateTokens(assistantContentToText(message.content));
239		let input = promptTokens;
240		let cacheRead = 0;
241		let cacheWrite = 0;
242		const sessionId = options?.sessionId;
243	
244		if (sessionId && options?.cacheRetention !== "none") {
245			const previousPrompt = promptCache.get(sessionId);
246			if (previousPrompt) {
247				const cachedChars = commonPrefixLength(previousPrompt, promptText);
248				cacheRead = estimateTokens(previousPrompt.slice(0, cachedChars));
249				cacheWrite = estimateTokens(promptText.slice(cachedChars));
250				input = Math.max(0, promptTokens - cacheRead);
251			} else {
252				cacheWrite = promptTokens;
253			}
254			promptCache.set(sessionId, promptText);
255		}
256	
257		return {
258			...message,
259			usage: {
260				input,
261				output: outputTokens,
262				cacheRead,
263				cacheWrite,
264				totalTokens: input + outputTokens + cacheRead + cacheWrite,
265				cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
266			},
267		};
268	}
269	
270	function splitStringByTokenSize(text: string, minTokenSize: number, maxTokenSize: number): string[] {
271		const chunks: string[] = [];
272		let index = 0;
273		while (index < text.length) {
274			const tokenSize = minTokenSize + Math.floor(Math.random() * (maxTokenSize - minTokenSize + 1));
275			const charSize = Math.max(1, tokenSize * 4);
276			chunks.push(text.slice(index, index + charSize));
277			index += charSize;
278		}
279		return chunks.length > 0 ? chunks : [""];
280	}
281	
282	function cloneMessage(message: AssistantMessage, api: string, provider: string, modelId: string): AssistantMessage {
283		const cloned = structuredClone(message);
284		return {
285			...cloned,
286			api,
287			provider,
288			model: modelId,
289			timestamp: cloned.timestamp ?? Date.now(),
290			usage: cloned.usage ?? DEFAULT_USAGE,
291		};
292	}
293	
294	function createDeferredMessage(model: Model<string>, handle: DeferredHandle): AssistantMessage {
295		return {
296			role: "assistant",
297			content: [],
298			api: model.api,
299			provider: model.provider,
300			model: model.id,
301			usage: DEFAULT_USAGE,
302			stopReason: "deferred",
303			deferred: handle,
304			timestamp: Date.now(),
305		};
306	}
307	
308	function createErrorMessage(error: unknown, api: string, provider: string, modelId: string): AssistantMessage {
309		return {
310			role: "assistant",
311			content: [],
312			api,
313			provider,
314			model: modelId,
315			usage: DEFAULT_USAGE,
316			stopReason: "error",
317			errorMessage: error instanceof Error ? error.message : String(error),
318			timestamp: Date.now(),
319		};
320	}
321	
322	function createAbortedMessage(partial: AssistantMessage): AssistantMessage {
323		return {
324			...partial,
325			stopReason: "aborted",
326			errorMessage: "Request was aborted",
327			timestamp: Date.now(),
328		};
329	}
330	
331	function scheduleChunk(chunk: string, tokensPerSecond: number | undefined): Promise<void> {
332		if (!tokensPerSecond || tokensPerSecond <= 0) {
333			return new Promise((resolve) => queueMicrotask(resolve));
334		}
335		const delayMs = (estimateTokens(chunk) / tokensPerSecond) * 1000;
336		return new Promise((resolve) => setTimeout(resolve, delayMs));
337	}
338	
339	async function streamWithDeltas(
340		stream: AssistantMessageEventStream,
341		message: AssistantMessage,
342		minTokenSize: number,
343		maxTokenSize: number,
344		tokensPerSecond: number | undefined,
345		signal: AbortSignal | undefined,
346	): Promise<void> {
347		const partial: AssistantMessage = { ...message, content: [], stopReason: "pending" };
348		if (signal?.aborted) {
349			const aborted = createAbortedMessage(partial);
350			stream.push({ type: "error", reason: "aborted", error: aborted });
351			stream.end(aborted);
352			return;
353		}
354	
355		stream.push({ type: "start", partial: { ...partial } });
356	
357		for (let index = 0; index < message.content.length; index++) {
358			if (signal?.aborted) {
359				const aborted = createAbortedMessage(partial);
360				stream.push({ type: "error", reason: "aborted", error: aborted });
361				stream.end(aborted);
362				return;
363			}
364	
365			const block = message.content[index];
366	
367			if (block.type === "thinking") {
368				partial.content = [...partial.content, { type: "thinking", thinking: "" }];
369				stream.push({ type: "thinking_start", contentIndex: index, partial: { ...partial } });
370				for (const chunk of splitStringByTokenSize(block.thinking, minTokenSize, maxTokenSize)) {
371					await scheduleChunk(chunk, tokensPerSecond);
372					if (signal?.aborted) {
373						const aborted = createAbortedMessage(partial);
374						stream.push({ type: "error", reason: "aborted", error: aborted });
375						stream.end(aborted);
376						return;
377					}
378					(partial.content[index] as ThinkingContent).thinking += chunk;
379					stream.push({ type: "thinking_delta", contentIndex: index, delta: chunk, partial: { ...partial } });
380				}
381				stream.push({
382					type: "thinking_end",
383					contentIndex: index,
384					content: block.thinking,
385					partial: { ...partial },
386				});
387				continue;
388			}
389	
390			if (block.type === "text") {
391				partial.content = [...partial.content, { type: "text", text: "" }];
392				stream.push({ type: "text_start", contentIndex: index, partial: { ...partial } });
393				for (const chunk of splitStringByTokenSize(block.text, minTokenSize, maxTokenSize)) {
394					await scheduleChunk(chunk, tokensPerSecond);
395					if (signal?.aborted) {
396						const aborted = createAbortedMessage(partial);
397						stream.push({ type: "error", reason: "aborted", error: aborted });
398						stream.end(aborted);
399						return;
400					}
401					(partial.content[index] as TextContent).text += chunk;
402					stream.push({ type: "text_delta", contentIndex: index, delta: chunk, partial: { ...partial } });
403				}
404				stream.push({ type: "text_end", contentIndex: index, content: block.text, partial: { ...partial } });
405				continue;
406			}
407	
408			partial.content = [...partial.content, { type: "toolCall", id: block.id, name: block.name, arguments: {} }];
409			stream.push({ type: "toolcall_start", contentIndex: index, partial: { ...partial } });
410			for (const chunk of splitStringByTokenSize(JSON.stringify(block.arguments), minTokenSize, maxTokenSize)) {
411				await scheduleChunk(chunk, tokensPerSecond);
412				if (signal?.aborted) {
413					const aborted = createAbortedMessage(partial);
414					stream.push({ type: "error", reason: "aborted", error: aborted });
415					stream.end(aborted);
416					return;
417				}
418				stream.push({ type: "toolcall_delta", contentIndex: index, delta: chunk, partial: { ...partial } });
419			}
420			(partial.content[index] as ToolCall).arguments = block.arguments;
421			stream.push({ type: "toolcall_end", contentIndex: index, toolCall: block, partial: { ...partial } });
422		}
423	
424		if (message.stopReason === "pending") {
425			throw new Error("Faux response ended without a stop reason");
426		}
427		if (message.stopReason === "error" || message.stopReason === "aborted") {
428			stream.push({ type: "error", reason: message.stopReason, error: message });
429			stream.end(message);
430			return;
431		}
432	
433		stream.push({ type: "done", reason: message.stopReason, message });
434		stream.end(message);
435	}
436	
437	export function createFauxCore(options: RegisterFauxProviderOptions) {
438		const api = options.api ?? randomId(DEFAULT_API);
439		const provider = options.provider ?? DEFAULT_PROVIDER;
440		const minTokenSize = Math.max(
441			1,
442			Math.min(options.tokenSize?.min ?? DEFAULT_MIN_TOKEN_SIZE, options.tokenSize?.max ?? DEFAULT_MAX_TOKEN_SIZE),
443		);
444		const maxTokenSize = Math.max(minTokenSize, options.tokenSize?.max ?? DEFAULT_MAX_TOKEN_SIZE);
445		let pendingResponses: FauxResponseStep[] = [];
446		const tokensPerSecond = options.tokensPerSecond;
447		const state: FauxProviderState = { callCount: 0, deferredFetchCount: 0, cancelledDeferred: [] };
448		const promptCache = new Map<string, string>();
449		const deferredResponses = new Map<
450			string,
451			{
452				handle: DeferredHandle;
453				step: FauxResponseStep;
454				context: TranscriptContext;
455				options: SimpleStreamOptions | undefined;
456				model: Model<string>;
457				pendingFetches: number;
458				cancelled: boolean;
459				final?: AssistantMessage;
460			}
461		>();
462	
463		const modelDefinitions = options.models?.length
464			? options.models
465			: [
466					{
467						id: DEFAULT_MODEL_ID,
468						name: DEFAULT_MODEL_NAME,
469						reasoning: false,
470						input: ["text", "image"] as ("text" | "image")[],
471						cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
472						contextWindow: 128000,
473						maxTokens: 16384,
474					},
475				];
476		const models = modelDefinitions.map((definition) => ({
477			id: definition.id,
478			name: definition.name ?? definition.id,
479			api,
480			provider,
481			baseUrl: DEFAULT_BASE_URL,
482			reasoning: definition.reasoning ?? false,
483			input: definition.input ?? ["text", "image"],
484			inputLimits: definition.inputLimits,
485			cost: definition.cost ?? { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
486			contextWindow: definition.contextWindow ?? 128000,
487			maxTokens: definition.maxTokens ?? 16384,
488		})) as [Model<string>, ...Model<string>[]];
489	
490		const resolveResponse = async (
491			step: FauxResponseStep,
492			context: TranscriptContext,
493			streamOptions: SimpleStreamOptions | undefined,
494			requestModel: Model<string>,
495		): Promise<AssistantMessage> => {
496			const resolved = typeof step === "function" ? await step(context, streamOptions, state, requestModel) : step;
497			return withUsageEstimate(
498				cloneMessage(resolved, api, provider, requestModel.id),
499				context,
500				streamOptions,
501				promptCache,
502			);
503		};
504	
505		const stream: StreamFunction<string, SimpleStreamOptions> = (requestModel, context, streamOptions) => {
506			const outer = createAssistantMessageEventStream();
507			const step = pendingResponses.shift();
508			state.callCount++;
509	
510			queueMicrotask(async () => {
511				try {
512					await streamOptions?.onResponse?.({ status: 200, headers: {} }, requestModel);
513					if (!step) {
514						let message = createErrorMessage(
515							new Error("No more faux responses queued"),
516							api,
517							provider,
518							requestModel.id,
519						);
520						message = withUsageEstimate(message, context, streamOptions, promptCache);
521						outer.push({ type: "error", reason: "error", error: message });
522						outer.end(message);
523						return;
524					}
525	
526					if (streamOptions?.deferred) {
527						const handle: DeferredHandle = {
528							provider: requestModel.provider,
529							modelId: requestModel.id,
530							api: requestModel.api,
531							id: randomId("deferred"),
532							...(options.deferred?.pollAfterMs !== undefined ? { pollAfterMs: options.deferred.pollAfterMs } : {}),
533						};
534						deferredResponses.set(handle.id, {
535							handle,
536							step,
537							context,
538							options: streamOptions,
539							model: requestModel,
540							pendingFetches: Math.max(0, Math.floor(options.deferred?.pendingFetches ?? 0)),
541							cancelled: false,
542						});
543						await streamWithDeltas(
544							outer,
545							createDeferredMessage(requestModel, handle),
546							minTokenSize,
547							maxTokenSize,
548							tokensPerSecond,
549							streamOptions.signal,
550						);
551						return;
552					}
553	
554					const message = await resolveResponse(step, context, streamOptions, requestModel);
555					await streamWithDeltas(outer, message, minTokenSize, maxTokenSize, tokensPerSecond, streamOptions?.signal);
556				} catch (error) {
557					const message = createErrorMessage(error, api, provider, requestModel.id);
558					outer.push({ type: "error", reason: "error", error: message });
559					outer.end(message);
560				}
561			});
562	
563			return outer;
564		};
565	
566		const streamSimple: StreamFunction<string, SimpleStreamOptions> = (streamModel, context, streamOptions) =>
567			stream(streamModel, context, streamOptions);
568	
569		const fetchDeferred = (
570			requestModel: Model<string>,
571			handle: DeferredHandle,
572			fetchOptions?: DeferredFetchOptions,
573		): AssistantMessageEventStream => {
574			const outer = createAssistantMessageEventStream();
575			state.deferredFetchCount++;
576	
577			queueMicrotask(async () => {
578				try {
579					await fetchOptions?.onResponse?.({ status: 200, headers: {} }, requestModel);
580					const entry = deferredResponses.get(handle.id);
581					if (
582						!entry ||
583						entry.handle.provider !== handle.provider ||
584						entry.handle.modelId !== handle.modelId ||
585						entry.handle.api !== handle.api
586					) {
587						throw new Error(`Unknown faux deferred response: ${handle.id}`);
588					}
589					if (entry.cancelled) throw new Error(`Faux deferred response was cancelled: ${handle.id}`);
590	
591					if (entry.pendingFetches > 0) {
592						entry.pendingFetches--;
593						await streamWithDeltas(
594							outer,
595							createDeferredMessage(requestModel, entry.handle),
596							minTokenSize,
597							maxTokenSize,
598							tokensPerSecond,
599							fetchOptions?.signal,
600						);
601						return;
602					}
603	
604					if (!entry.final) {
605						const {
606							deferred: _deferred,
607							signal: _submissionSignal,
608							onResponse: _submissionOnResponse,
609							...submissionOptions
610						} = entry.options ?? {};
611						try {
612							entry.final = await resolveResponse(entry.step, entry.context, submissionOptions, entry.model);
613						} catch (error) {
614							entry.final = createErrorMessage(error, api, provider, entry.model.id);
615						}
616					}
617					await streamWithDeltas(
618						outer,
619						entry.final,
620						minTokenSize,
621						maxTokenSize,
622						tokensPerSecond,
623						fetchOptions?.signal,
624					);
625				} catch (error) {
626					const message = createErrorMessage(error, api, provider, requestModel.id);
627					outer.push({ type: "error", reason: "error", error: message });
628					outer.end(message);
629				}
630			});
631	
632			return outer;
633		};
634	
635		const cancelDeferred = async (
636			requestModel: Model<string>,
637			handle: DeferredHandle,
638			cancelOptions?: DeferredCancelOptions,
639		): Promise<void> => {
640			state.cancelledDeferred.push(structuredClone(handle));
641			const entry = deferredResponses.get(handle.id);
642			if (entry) entry.cancelled = true;
643			await cancelOptions?.onResponse?.({ status: 200, headers: {} }, requestModel);
644		};
645	
646		function getModel(): Model<string>;
647		function getModel(requestedModelId: string): Model<string> | undefined;
648		function getModel(requestedModelId?: string): Model<string> | undefined {
649			if (!requestedModelId) {
650				return models[0];
651			}
652			return models.find((candidate) => candidate.id === requestedModelId);
653		}
654	
655		return {
656			api,
657			provider,
658			models,
659			stream,
660			streamSimple,
661			fetchDeferred,
662			cancelDeferred,
663			getModel,
664			state,
665			setResponses(responses: FauxResponseStep[]) {
666				pendingResponses = [...responses];
667			},
668			appendResponses(responses: FauxResponseStep[]) {
669				pendingResponses.push(...responses);
670			},
671			getPendingResponseCount() {
672				return pendingResponses.length;
673			},
674		};
675	}
676	
677	/**
678	 * Faux provider for tests built on explicit `Models` collections:
679	 *
680	 * ```ts
681	 * const faux = fauxProvider();
682	 * const models = createModels();
683	 * models.setProvider(faux.provider);
684	 * faux.setResponses([fauxAssistantMessage("hi")]);
685	 * ```
686	 */
687	export function fauxProvider(options: RegisterFauxProviderOptions = {}): FauxProviderHandle {
688		const core = createFauxCore(options);
689		const provider = createProvider({
690			id: core.provider,
691			auth: { apiKey: { name: "Faux", resolve: async () => ({ auth: {} }) } },
692			models: core.models,
693			api: {
694				stream: core.stream,
695				streamSimple: core.streamSimple,
696				fetchDeferred: core.fetchDeferred,
697				cancelDeferred: core.cancelDeferred,
698			},
699		});
700		return {
701			provider,
702			api: core.api,
703			models: core.models,
704			getModel: core.getModel,
705			state: core.state,
706			setResponses: core.setResponses,
707			appendResponses: core.appendResponses,
708			getPendingResponseCount: core.getPendingResponseCount,
709		};
710	}
