1	import { Compile } from "typebox/compile";
2	import type { TLocalizedValidationError } from "typebox/error";
3	import { Value } from "typebox/value";
4	import type { Tool, ToolCall } from "../types.ts";
5	
6	const validatorCache = new WeakMap<object, ReturnType<typeof Compile>>();
7	const TYPEBOX_KIND = Symbol.for("TypeBox.Kind");
8	
9	interface JsonSchemaObject {
10		type?: string | string[];
11		properties?: Record<string, JsonSchemaObject>;
12		required?: string[];
13		items?: JsonSchemaObject | JsonSchemaObject[];
14		additionalProperties?: boolean | JsonSchemaObject;
15		allOf?: JsonSchemaObject[];
16		anyOf?: JsonSchemaObject[];
17		oneOf?: JsonSchemaObject[];
18	}
19	
20	function getSchemaTypes(schema: JsonSchemaObject): string[] {
21		if (typeof schema.type === "string") {
22			return [schema.type];
23		}
24		if (Array.isArray(schema.type)) {
25			return schema.type.filter((type): type is string => typeof type === "string");
26		}
27		return [];
28	}
29	
30	function matchesJsonType(value: unknown, type: string): boolean {
31		switch (type) {
32			case "number":
33				return typeof value === "number";
34			case "integer":
35				return typeof value === "number" && Number.isInteger(value);
36			case "boolean":
37				return typeof value === "boolean";
38			case "string":
39				return typeof value === "string";
40			case "null":
41				return value === null;
42			case "array":
43				return Array.isArray(value);
44			case "object":
45				return typeof value === "object" && value !== null && !Array.isArray(value);
46			default:
47				return false;
48		}
49	}
50	
51	function getSubSchemaValidator(schema: JsonSchemaObject): ReturnType<typeof Compile> | undefined {
52		try {
53			return getValidator(schema as Tool["parameters"]);
54		} catch {
55			return undefined;
56		}
57	}
58	
59	function coercePrimitiveByType(value: unknown, type: string): unknown {
60		switch (type) {
61			case "number": {
62				if (value === null) {
63					return 0;
64				}
65				if (typeof value === "string" && value.trim() !== "") {
66					const parsed = Number(value);
67					if (Number.isFinite(parsed)) {
68						return parsed;
69					}
70				}
71				if (typeof value === "boolean") {
72					return value ? 1 : 0;
73				}
74				return value;
75			}
76			case "integer": {
77				if (value === null) {
78					return 0;
79				}
80				if (typeof value === "string" && value.trim() !== "") {
81					const parsed = Number(value);
82					if (Number.isInteger(parsed)) {
83						return parsed;
84					}
85				}
86				if (typeof value === "boolean") {
87					return value ? 1 : 0;
88				}
89				return value;
90			}
91			case "boolean": {
92				if (value === null) {
93					return false;
94				}
95				if (typeof value === "string") {
96					if (value === "true") {
97						return true;
98					}
99					if (value === "false") {
100						return false;
101					}
102				}
103				if (typeof value === "number") {
104					if (value === 1) {
105						return true;
106					}
107					if (value === 0) {
108						return false;
109					}
110				}
111				return value;
112			}
113			case "string": {
114				if (value === null) {
115					return "";
116				}
117				if (typeof value === "number" || typeof value === "boolean") {
118					return String(value);
119				}
120				return value;
121			}
122			case "null": {
123				if (value === "" || value === 0 || value === false) {
124					return null;
125				}
126				return value;
127			}
128			default:
129				return value;
130		}
131	}
132	
133	function applySchemaObjectCoercion(value: Record<string, unknown>, schema: JsonSchemaObject): void {
134		const properties = schema.properties;
135		const definedKeys = new Set<string>(properties ? Object.keys(properties) : []);
136	
137		if (properties) {
138			for (const [key, propertySchema] of Object.entries(properties)) {
139				if (!(key in value)) {
140					continue;
141				}
142				value[key] = coerceWithJsonSchema(value[key], propertySchema);
143			}
144		}
145	
146		if (schema.additionalProperties && typeof schema.additionalProperties === "object") {
147			for (const [key, propertyValue] of Object.entries(value)) {
148				if (definedKeys.has(key)) {
149					continue;
150				}
151				value[key] = coerceWithJsonSchema(propertyValue, schema.additionalProperties);
152			}
153		}
154	}
155	
156	function applySchemaArrayCoercion(value: unknown[], schema: JsonSchemaObject): void {
157		if (Array.isArray(schema.items)) {
158			for (let index = 0; index < value.length; index++) {
159				const itemSchema = schema.items[index];
160				if (!itemSchema) {
161					continue;
162				}
163				value[index] = coerceWithJsonSchema(value[index], itemSchema);
164			}
165			return;
166		}
167	
168		if (schema.items && typeof schema.items === "object") {
169			for (let index = 0; index < value.length; index++) {
170				value[index] = coerceWithJsonSchema(value[index], schema.items);
171			}
172		}
173	}
174	
175	function coerceWithUnionSchema(value: unknown, schemas: JsonSchemaObject[]): unknown {
176		for (const schema of schemas) {
177			const validator = getSubSchemaValidator(schema);
178			if (validator?.Check(value)) {
179				return value;
180			}
181		}
182	
183		for (const schema of schemas) {
184			const candidate = structuredClone(value);
185			const coerced = coerceWithJsonSchema(candidate, schema);
186			const validator = getSubSchemaValidator(schema);
187			if (validator?.Check(coerced)) {
188				return coerced;
189			}
190		}
191		return value;
192	}
193	
194	function coerceWithJsonSchema(value: unknown, schema: JsonSchemaObject): unknown {
195		let nextValue = value;
196	
197		if (Array.isArray(schema.allOf)) {
198			for (const nested of schema.allOf) {
199				nextValue = coerceWithJsonSchema(nextValue, nested);
200			}
201		}
202	
203		if (Array.isArray(schema.anyOf)) {
204			nextValue = coerceWithUnionSchema(nextValue, schema.anyOf);
205		}
206	
207		if (Array.isArray(schema.oneOf)) {
208			nextValue = coerceWithUnionSchema(nextValue, schema.oneOf);
209		}
210	
211		const schemaTypes = getSchemaTypes(schema);
212		const matchesUnionMember =
213			schemaTypes.length > 1 && schemaTypes.some((schemaType) => matchesJsonType(nextValue, schemaType));
214		if (schemaTypes.length > 0 && !matchesUnionMember) {
215			for (const schemaType of schemaTypes) {
216				const candidate = coercePrimitiveByType(nextValue, schemaType);
217				if (candidate !== nextValue) {
218					nextValue = candidate;
219					break;
220				}
221			}
222		}
223	
224		if (
225			schemaTypes.includes("object") &&
226			typeof nextValue === "object" &&
227			nextValue !== null &&
228			!Array.isArray(nextValue)
229		) {
230			applySchemaObjectCoercion(nextValue as Record<string, unknown>, schema);
231		}
232	
233		if (schemaTypes.includes("array") && Array.isArray(nextValue)) {
234			applySchemaArrayCoercion(nextValue, schema);
235		}
236	
237		return nextValue;
238	}
239	
240	function normalizeOptionalNulls(value: unknown, schema: JsonSchemaObject): void {
241		if (Array.isArray(value)) {
242			if (Array.isArray(schema.items)) {
243				for (let index = 0; index < value.length; index++) {
244					const itemSchema = schema.items[index];
245					if (itemSchema) normalizeOptionalNulls(value[index], itemSchema);
246				}
247			} else if (schema.items) {
248				for (const item of value) normalizeOptionalNulls(item, schema.items);
249			}
250			return;
251		}
252		if (typeof value !== "object" || value === null || !schema.properties) return;
253	
254		const object = value as Record<string, unknown>;
255		const required = new Set(schema.required ?? []);
256		for (const [key, propertySchema] of Object.entries(schema.properties)) {
257			if (!(key in object)) continue;
258			if (
259				object[key] === null &&
260				!required.has(key) &&
261				typeof (propertySchema as { $ref?: unknown }).$ref !== "string" &&
262				getSubSchemaValidator(propertySchema)?.Check(null) === false
263			) {
264				delete object[key];
265			} else {
266				normalizeOptionalNulls(object[key], propertySchema);
267			}
268		}
269	}
270	
271	function getValidator(schema: Tool["parameters"]): ReturnType<typeof Compile> {
272		const key = schema as object;
273		const cached = validatorCache.get(key);
274		if (cached) {
275			return cached;
276		}
277		const validator = Compile(schema);
278		validatorCache.set(key, validator);
279		return validator;
280	}
281	
282	function formatValidationPath(error: TLocalizedValidationError): string {
283		if (error.keyword === "required") {
284			const requiredProperties = (error.params as { requiredProperties?: string[] }).requiredProperties;
285			const requiredProperty = requiredProperties?.[0];
286			if (requiredProperty) {
287				const basePath = error.instancePath.replace(/^\//, "").replace(/\//g, ".");
288				return basePath ? `${basePath}.${requiredProperty}` : requiredProperty;
289			}
290		}
291		const path = error.instancePath.replace(/^\//, "").replace(/\//g, ".");
292		return path || "root";
293	}
294	
295	/**
296	 * Finds a tool by name and validates the tool call arguments against its TypeBox schema
297	 * @param tools Array of tool definitions
298	 * @param toolCall The tool call from the LLM
299	 * @returns The validated arguments
300	 * @throws Error if tool is not found or validation fails
301	 */
302	export function validateToolCall(tools: Tool[], toolCall: ToolCall): any {
303		const tool = tools.find((t) => t.name === toolCall.name);
304		if (!tool) {
305			throw new Error(`Tool "${toolCall.name}" not found`);
306		}
307		return validateToolArguments(tool, toolCall);
308	}
309	
310	/**
311	 * Validates tool call arguments against the tool's TypeBox schema
312	 * @param tool The tool definition with TypeBox schema
313	 * @param toolCall The tool call from the LLM
314	 * @returns The validated (and potentially coerced) arguments
315	 * @throws Error with formatted message if validation fails
316	 */
317	export function validateToolArguments(tool: Tool, toolCall: ToolCall): any {
318		const args = structuredClone(toolCall.arguments);
319		normalizeOptionalNulls(args, tool.parameters as JsonSchemaObject);
320		Value.Convert(tool.parameters, args);
321	
322		const validator = getValidator(tool.parameters);
323		if (!Object.getOwnPropertySymbols(tool.parameters).includes(TYPEBOX_KIND)) {
324			const coerced = coerceWithJsonSchema(args, tool.parameters as JsonSchemaObject);
325			if (coerced !== args) {
326				if (typeof args === "object" && args !== null && typeof coerced === "object" && coerced !== null) {
327					for (const key of Object.keys(args)) {
328						delete args[key];
329					}
330					Object.assign(args, coerced);
331				} else {
332					return validator.Check(coerced) ? coerced : args;
333				}
334			}
335		}
336	
337		if (validator.Check(args)) {
338			return args;
339		}
340	
341		const errors =
342			validator
343				.Errors(args)
344				.map((error) => `  - ${formatValidationPath(error)}: ${error.message}`)
345				.join("\n") || "Unknown validation error";
346	
347		const errorMessage = `Validation failed for tool "${toolCall.name}":\n${errors}\n\nReceived arguments:\n${JSON.stringify(toolCall.arguments, null, 2)}`;
348	
349		throw new Error(errorMessage);
350	}
