// Minimal agent demo using pi's real Agent class and the built-in faux (scripted) model.
// No API key needed: the "model" replays scripted responses, but the loop, tool
// validation, tool execution and event stream are the real pi code.
import {
	createModels,
	fauxAssistantMessage,
	fauxProvider,
	fauxText,
	fauxToolCall,
	Type,
} from "file:///C:/files/src/pi/packages/ai/dist/index.js";
import { Agent } from "file:///C:/files/src/pi/packages/agent/dist/index.js";

// --- 1. A fake file system the tool can read -------------------------------
const files = { "config.json": '{ "port": 8080, "host": "localhost" }' };

// --- 2. A tool: name + description + JSON schema + execute() ---------------
const readFileTool = {
	name: "read_file",
	label: "Read File",
	description: "Read a file's contents",
	parameters: Type.Object({ path: Type.String({ description: "File path" }) }),
	async execute(_toolCallId, params) {
		const content = files[params.path];
		if (content === undefined) throw new Error(`File not found: ${params.path}`);
		return { content: [{ type: "text", text: content }], details: {} };
	},
};

// --- 3. A scripted "model" ----------------------------------------------------
const faux = fauxProvider();
const models = createModels();
models.setProvider(faux.provider);
const contextsSeenByModel = [];
faux.setResponses([
	// Call 1: the model decides it needs the tool. It only *asks*; pi executes.
	(context) => {
		contextsSeenByModel.push(context.messages.map((m) => m.role));
		return fauxAssistantMessage(
			[fauxText("I'll read the file."), fauxToolCall("read_file", { path: "config.json" }, { id: "call_1" })],
			{ stopReason: "toolUse" },
		);
	},
	// Call 2: the model receives the whole history again, including the tool result.
	(context) => {
		contextsSeenByModel.push(context.messages.map((m) => m.role));
		const toolResult = context.messages.find((m) => m.role === "toolResult");
		const port = JSON.parse(toolResult.content[0].text).port;
		return fauxAssistantMessage(`The port is ${port}.`, { stopReason: "stop" });
	},
]);

// --- 4. The agent -------------------------------------------------------------
const agent = new Agent({
	initialState: {
		systemPrompt: "You are a helpful assistant.",
		model: faux.getModel(),
		tools: [readFileTool],
	},
	streamFn: models.streamSimple.bind(models),
});

agent.subscribe((event) => {
	switch (event.type) {
		case "message_update":
			return; // too noisy: one per streamed chunk
		case "message_start":
		case "message_end":
			console.log(`${event.type.padEnd(22)} role=${event.message.role}`);
			return;
		case "tool_execution_start":
			console.log(`${event.type.padEnd(22)} ${event.toolName}(${JSON.stringify(event.args)})`);
			return;
		case "tool_execution_end":
			console.log(`${event.type.padEnd(22)} isError=${event.isError}`);
			return;
